insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e8000000-0000-0000-0000-000000000001', 'ukmla', '755d24f5-5b08-4a3f-968d-f1913cbbb7ce',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e8000000-0000-0000-0000-000000000001', 'A', 'MRI of the hip', false, 'Ruled out because MRI is not first-line for typical osteoarthritis; it is reserved for atypical presentations, suspected avascular necrosis, or when plain films are inconclusive.', 1),
('e8000000-0000-0000-0000-000000000001', 'B', 'Hip ultrasound', false, 'Ruled out because ultrasound is useful for effusions or soft tissue pathology but does not assess the bony changes needed to diagnose osteoarthritis.', 2),
('e8000000-0000-0000-0000-000000000001', 'C', 'Plain weight-bearing radiograph of the pelvis and hip', true, 'Correct. Plain radiographs are the first-line investigation for suspected osteoarthritis, showing joint space narrowing, subchondral sclerosis, osteophytes and subchondral cysts, and help confirm the diagnosis and severity before considering referral for joint replacement.', 3),
('e8000000-0000-0000-0000-000000000001', 'D', 'Serum rheumatoid factor and anti-CCP antibodies', false, 'Ruled out because the clinical picture (mechanical pain, brief morning stiffness, older patient) is typical of osteoarthritis rather than an inflammatory arthropathy, so autoantibody testing is not indicated first.', 4),
('e8000000-0000-0000-0000-000000000001', 'E', 'CT of the hip', false, 'Ruled out because CT is not required for routine assessment of osteoarthritis and involves higher radiation exposure than plain film with no diagnostic advantage in this context.', 5),
('e8000000-0000-0000-0000-000000000002', 'A', 'Intra-articular corticosteroid injection as definitive long-term treatment', false, 'Ruled out because intra-articular steroids provide only short-term symptomatic relief and are not a substitute for referral when conservative management has already failed and function is significantly impaired.', 1),
('e8000000-0000-0000-0000-000000000002', 'B', 'Commence oral opioid analgesia for long-term pain control', false, 'Ruled out because long-term opioids are not recommended for chronic non-cancer musculoskeletal pain due to limited efficacy and risk of dependence; referral for definitive treatment is more appropriate.', 2),
('e8000000-0000-0000-0000-000000000002', 'C', 'Arrange knee arthroscopy for washout', false, 'Ruled out because arthroscopic washout/debridement has no proven benefit in osteoarthritis and is not recommended as a treatment for degenerative knee disease.', 3),
('e8000000-0000-0000-0000-000000000002', 'D', 'Refer for orthopaedic assessment for consideration of total knee replacement', true, 'Correct. When conservative measures (analgesia, weight loss, exercise) have failed and symptoms substantially affect quality of life, referral for joint replacement is the appropriate next step, particularly with radiographically severe disease.', 4),
('e8000000-0000-0000-0000-000000000002', 'E', 'Continue current management and review in 12 months', false, 'Ruled out because this delays definitive treatment in a patient who has already exhausted conservative options and has significant functional impairment.', 5),
('e8000000-0000-0000-0000-000000000003', 'A', 'Urgent referral back to the orthopaedic team for assessment and likely joint aspiration/wound exploration', true, 'Correct. Signs of a surgical site infection after joint replacement (increasing pain, erythema, discharge, raised CRP) raise concern for prosthetic joint infection, which requires urgent orthopaedic assessment; early recognition and washout/debridement can preserve the implant if caught early (DAIR).', 1),
('e8000000-0000-0000-0000-000000000003', 'B', 'Reassure the patient that this is normal post-operative healing and review in 6 weeks', false, 'Ruled out because worsening pain, discharge and rising inflammatory markers 10 days post-operatively are red flags for infection, not normal healing, and require urgent assessment.', 2),
('e8000000-0000-0000-0000-000000000003', 'C', 'Start empirical oral antibiotics in the community without further assessment', false, 'Ruled out because suspected prosthetic joint infection requires specialist assessment, imaging/aspiration to identify the organism, and often surgical intervention rather than blind community antibiotics, which can mask infection and complicate management.', 3),
('e8000000-0000-0000-0000-000000000003', 'D', 'Arrange an outpatient MRI in 4 weeks', false, 'Ruled out because this delays urgent assessment; MRI is also of limited use near a metal implant and outpatient timelines are inappropriate for a suspected acute prosthetic infection.', 4),
('e8000000-0000-0000-0000-000000000003', 'E', 'Advise wound care with dressings only and no further action', false, 'Ruled out because this fails to address a likely infective process with systemic and local signs requiring specialist input.', 5),
('e8000000-0000-0000-0000-000000000004', 'A', 'No VTE prophylaxis is required as knee replacement carries low VTE risk', false, 'Ruled out because major lower limb arthroplasty carries a substantial VTE risk and requires prophylaxis; this is a well-established standard of care.', 1),
('e8000000-0000-0000-0000-000000000004', 'B', 'Mechanical prophylaxis plus pharmacological prophylaxis (e.g. low molecular weight heparin) should be offered post-operatively unless contraindicated', true, 'Correct. NICE guidance recommends combined mechanical (e.g. compression stockings/intermittent pneumatic compression) and pharmacological VTE prophylaxis after major lower limb orthopaedic surgery such as knee replacement, continued for an appropriate duration post-operatively, given the significant VTE risk with this surgery.', 2),
('e8000000-0000-0000-0000-000000000004', 'C', 'Aspirin alone is sufficient with no mechanical prophylaxis needed', false, 'Ruled out because while aspirin can be used as part of extended prophylaxis in some protocols, combined mechanical and pharmacological prophylaxis (typically LMWH or equivalent) is the recommended standard immediately post-operatively unless contraindicated.', 3),
('e8000000-0000-0000-0000-000000000004', 'D', 'Full-dose therapeutic anticoagulation should be started immediately post-operatively', false, 'Ruled out because full therapeutic-dose anticoagulation is not indicated for routine VTE prophylaxis after elective arthroplasty and significantly increases bleeding risk; prophylactic dosing is used.', 4),
('e8000000-0000-0000-0000-000000000004', 'E', 'VTE prophylaxis should be delayed until the patient is fully mobile', false, 'Ruled out because prophylaxis should begin in the peri/post-operative period (once haemostasis is adequate), not delayed until full mobility is achieved, as risk is highest in the immediate post-operative period.', 5),
('e8000000-0000-0000-0000-000000000005', 'A', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis typically causes symmetrical small joint (MCP/PIP) synovitis with systemic inflammatory features and raised inflammatory markers, not an isolated CMC joint presentation with normal inflammatory markers.', 1),
('e8000000-0000-0000-0000-000000000005', 'B', $x$De Quervain's tenosynovitis$x$, false, $x$Ruled out because De Quervain's causes pain over the radial styloid with a positive Finkelstein's test due to tendon sheath inflammation, not joint line tenderness or a positive grind test at the CMC joint.$x$, 2),
('e8000000-0000-0000-0000-000000000005', 'C', 'Gout', false, 'Ruled out because gout typically presents with acute, severe, hot, swollen joint inflammation (often first MTP joint) rather than a chronic 6-month history of mechanical pain with normal inflammatory markers.', 3),
('e8000000-0000-0000-0000-000000000005', 'D', 'Carpal tunnel syndrome', false, 'Ruled out because carpal tunnel syndrome causes numbness/tingling in the median nerve distribution (thumb, index, middle, radial half of ring finger) and weakness of thumb abduction, not joint line pain and a positive grind test.', 4),
('e8000000-0000-0000-0000-000000000005', 'E', 'First carpometacarpal joint osteoarthritis', true, 'Correct. Pain and stiffness at the base of the thumb, worse with pinch/grip activities, joint line tenderness, a positive grind test and squaring of the joint are classic features of first CMC joint osteoarthritis, a common site for degenerative change in the hand.', 5),
('e8000000-0000-0000-0000-000000000006', 'A', 'Periprosthetic femoral fracture', false, 'Ruled out because although this can also cause sudden pain and inability to weight-bear, the classic limb position of shortening with internal rotation and adduction following a flexion/adduction/rotation movement is most typical of dislocation; fracture is usually associated with a fall or direct trauma rather than this movement pattern, though both should be assessed radiographically.', 1),
('e8000000-0000-0000-0000-000000000006', 'B', 'Deep vein thrombosis of the leg', false, 'Ruled out because DVT causes gradual-onset calf swelling, pain and warmth rather than sudden severe pain with a specific limb deformity following a provocative movement.', 2),
('e8000000-0000-0000-0000-000000000006', 'C', 'Posterior dislocation of the hip prosthesis', true, 'Correct. The posterior approach to hip replacement disrupts posterior stabilising structures, making the hip vulnerable to dislocation with combined flexion, adduction and internal rotation (e.g. bending and leg-crossing); the classic finding of a shortened, internally rotated, adducted leg with sudden pain and inability to weight-bear is typical of posterior dislocation.', 3),
('e8000000-0000-0000-0000-000000000006', 'D', 'Sciatic nerve palsy', false, 'Ruled out because nerve palsy causes weakness/sensory disturbance in the nerve distribution rather than a mechanical deformity with shortening and rotation of the limb.', 4),
('e8000000-0000-0000-0000-000000000006', 'E', 'Prosthetic joint infection', false, 'Ruled out because infection typically presents with a more insidious onset of pain, swelling and systemic features rather than sudden onset following a specific provocative movement with characteristic limb deformity.', 5),
('e8000000-0000-0000-0000-000000000007', 'A', $x$Heberden's nodes$x$, true, $x$Correct. Heberden's nodes are bony swellings at the distal interphalangeal (DIP) joints seen in nodal hand osteoarthritis, representing osteophyte formation, and are a classic examination finding distinguishing osteoarthritis from inflammatory arthropathies.$x$, 1),
('e8000000-0000-0000-0000-000000000007', 'B', $x$Bouchard's nodes$x$, false, $x$Ruled out because Bouchard's nodes occur at the proximal interphalangeal (PIP) joints, not the DIP joints described here.$x$, 2),
('e8000000-0000-0000-0000-000000000007', 'C', 'Rheumatoid nodules', false, 'Ruled out because rheumatoid nodules are subcutaneous nodules typically found over extensor surfaces (e.g. elbows) in rheumatoid arthritis, not bony DIP joint swellings.', 3),
('e8000000-0000-0000-0000-000000000007', 'D', 'Gouty tophi', false, 'Ruled out because tophi are deposits of urate crystals typically found at the ear, elbows or first MTP joint region in chronic gout, not typical bony DIP swellings of osteoarthritis.', 4),
('e8000000-0000-0000-0000-000000000007', 'E', $x$Dupuytren's contracture$x$, false, 'Ruled out because this refers to progressive thickening and contracture of the palmar fascia causing finger flexion deformity, not bony joint swellings.', 5),
('e8000000-0000-0000-0000-000000000008', 'A', 'Acute prosthetic joint infection', false, 'Ruled out because the elevated metal ion levels and chronic progressive course over months, rather than acute onset with fever/systemic illness, point to a metal debris reaction rather than acute infection, although infection should still be excluded as part of work-up.', 1),
('e8000000-0000-0000-0000-000000000008', 'B', 'Adverse reaction to metal debris (metallosis) with pseudotumour formation', true, 'Correct. Metal-on-metal hip implants can generate metal wear debris causing a local soft-tissue reaction (adverse reaction to metal debris/ARMD), with elevated serum cobalt/chromium, peri-prosthetic fluid collections (pseudotumours), pain and instability; this is a recognised long-term complication requiring specialist follow-up and often revision surgery.', 2),
('e8000000-0000-0000-0000-000000000008', 'C', 'Aseptic loosening unrelated to bearing surface', false, 'Ruled out because the specifically elevated cobalt/chromium levels with a metal-on-metal bearing strongly implicate a metal debris reaction rather than simple mechanical loosening, which would not typically raise metal ion levels.', 3),
('e8000000-0000-0000-0000-000000000008', 'D', 'Avascular necrosis of the native femoral head', false, 'Ruled out because the patient already has a hip replacement (the femoral head has been replaced), so native avascular necrosis is not relevant; also, this does not explain elevated metal ion levels.', 4),
('e8000000-0000-0000-0000-000000000008', 'E', 'Referred pain from lumbar spine pathology', false, 'Ruled out because the elevated metal ion levels and peri-prosthetic fluid collection localise the pathology to the hip implant itself, not the spine.', 5),
('e8000000-0000-0000-0000-000000000009', 'A', 'Weight loss has no effect on knee osteoarthritis symptoms and should not be recommended', false, 'Ruled out because weight loss reduces mechanical load on weight-bearing joints and has good evidence for reducing pain and improving function in knee osteoarthritis, making this statement incorrect.', 1),
('e8000000-0000-0000-0000-000000000009', 'B', 'Exercise should be avoided in osteoarthritis as it accelerates joint damage', false, 'Ruled out because appropriate therapeutic exercise is recommended and beneficial in osteoarthritis; it does not accelerate joint damage and instead improves muscle strength and joint stability.', 2),
('e8000000-0000-0000-0000-000000000009', 'C', 'Bariatric surgery is first-line before any other conservative measures are tried', false, 'Ruled out because bariatric surgery is not first-line management for osteoarthritis; core conservative measures including exercise, weight management support and analgesia are tried first.', 3),
('e8000000-0000-0000-0000-000000000009', 'D', 'Weight loss and structured exercise programmes are core, first-line interventions that can significantly reduce pain and improve function in knee osteoarthritis', true, 'Correct. NICE guidance identifies therapeutic exercise (strengthening and general aerobic fitness) and weight loss (if overweight/obese) as core first-line treatments for osteoarthritis, with good evidence for symptomatic improvement independent of other interventions.', 4),
('e8000000-0000-0000-0000-000000000009', 'E', 'Joint replacement should be offered before conservative measures are attempted in overweight patients', false, 'Ruled out because conservative management (exercise, weight loss, analgesia) is recommended before considering surgical referral, regardless of weight.', 5),
('e8000000-0000-0000-0000-000000000010', 'A', 'Urgent revision surgery to correct the leg length', false, 'Ruled out because revision surgery is not indicated for a mild, radiographically unremarkable leg length discrepancy with a well-fixed, well-positioned prosthesis and good functional mobility; this is a disproportionate intervention.', 1),
('e8000000-0000-0000-0000-000000000010', 'B', 'Immediate MRI to investigate for occult fracture', false, 'Ruled out because plain radiographs already show a well-positioned, well-fixed prosthesis with no fracture, so further imaging is not indicated for this benign finding.', 2),
('e8000000-0000-0000-0000-000000000010', 'C', 'Refer for below-knee amputation assessment', false, 'Ruled out because this is a wildly disproportionate response to a minor, expected leg length discrepancy and is not clinically indicated.', 3),
('e8000000-0000-0000-0000-000000000010', 'D', 'Discharge with no follow-up and no explanation to the patient', false, 'Ruled out because patients should be reassured and given an explanation, with practical solutions (such as a shoe raise) offered if the discrepancy is functionally troublesome; simply discharging without addressing the concern is suboptimal.', 4),
('e8000000-0000-0000-0000-000000000010', 'E', 'Reassure the patient and consider a shoe raise if the discrepancy causes functional difficulty', true, 'Correct. Mild leg length discrepancy is a recognised and common consequence of hip replacement (sometimes deliberately accepted to optimise joint stability), and in the absence of red flags (pain, instability, radiographic abnormality) it can be managed conservatively with reassurance and a shoe raise if symptomatic, rather than further surgery.', 5),
('e8000000-0000-0000-0000-000000000011', 'A', 'Photograph the wound, cover with a saline-soaked dressing, administer IV antibiotics and analgesia, align the limb, and arrange urgent orthopaedic and debridement referral', true, 'Correct. Open fractures require prompt IV antibiotics (to reduce infection risk), wound photography and covering with a saline-soaked dressing (to avoid repeated exposure), realignment and splinting, analgesia, and urgent orthopaedic assessment for surgical debridement, ideally within recommended time frames, following BOAST guidelines.', 1),
('e8000000-0000-0000-0000-000000000011', 'B', 'Repeatedly remove and replace the dressing at the bedside to inspect the wound', false, 'Ruled out because repeated exposure of an open fracture wound increases infection risk and contamination; the wound should be photographed once, covered, and left undisturbed until formal surgical debridement.', 2),
('e8000000-0000-0000-0000-000000000011', 'C', 'Delay antibiotics until the patient reaches theatre', false, 'Ruled out because IV antibiotics should be given as soon as possible after an open fracture, ideally at first assessment, to reduce the risk of infection, not delayed until theatre.', 3),
('e8000000-0000-0000-0000-000000000011', 'D', 'Attempt to close the wound primarily in the emergency department', false, 'Ruled out because open fracture wounds should not be closed in the emergency department; they require formal surgical debridement and often delayed closure or reconstruction in theatre due to contamination risk.', 4),
('e8000000-0000-0000-0000-000000000011', 'E', 'Apply a full circumferential plaster cast immediately without addressing the wound', false, 'Ruled out because a circumferential cast can mask ongoing bleeding, compartment syndrome or wound deterioration, and does not address the urgent need for antibiotics, wound care and surgical planning.', 5),
('e8000000-0000-0000-0000-000000000012', 'A', 'Increase the opioid dose and reassess in 2 hours', false, 'Ruled out because compartment syndrome pain is classically poorly responsive to opioids and requires immediate pressure-relieving action, not simply escalating analgesia and delaying reassessment, which risks irreversible muscle and nerve damage.', 1),
('e8000000-0000-0000-0000-000000000012', 'B', 'Elevate the limb above the level of the heart and reassess in the morning', false, 'Ruled out because elevation above heart level can reduce arterial perfusion pressure and worsen compartment syndrome; the limb should be kept at heart level, and this is a surgical emergency requiring immediate action, not delayed reassessment.', 2),
('e8000000-0000-0000-0000-000000000012', 'C', 'Reassure the patient that pain after a fracture is expected and continue current management', false, 'Ruled out because pain out of proportion to the injury, especially unrelieved by strong analgesia and worse on passive stretch, is a red flag for compartment syndrome, not simply expected post-fracture pain.', 3),
('e8000000-0000-0000-0000-000000000012', 'D', 'Urgently split/remove the cast completely and escalate immediately to the orthopaedic team for consideration of fasciotomy', true, 'Correct. This presentation (severe pain out of proportion to injury, unrelieved by strong analgesia, pain on passive stretch) is classic for acute compartment syndrome, a surgical emergency; the cast must be released immediately and the orthopaedic team informed urgently, as pulses may remain palpable even with compartment syndrome present, so their presence should not be reassuring.', 4),
('e8000000-0000-0000-0000-000000000012', 'E', 'Arrange a Doppler ultrasound of the leg before taking any action', false, 'Ruled out because compartment syndrome is a clinical diagnosis requiring immediate action (cast release, escalation); imaging should not delay definitive intervention, and Doppler assessing macrovascular flow does not reliably exclude compartment syndrome, where pulses are often preserved until late.', 5),
('e8000000-0000-0000-0000-000000000013', 'A', 'Anterior hip dislocation', false, 'Ruled out because native hip dislocation is rare without major trauma and typically presents with the leg flexed, abducted and externally rotated rather than shortened; this presentation is far more consistent with a fractured neck of femur following a low-energy fall in an osteoporotic patient.', 1),
('e8000000-0000-0000-0000-000000000013', 'B', 'Pubic ramus fracture', false, 'Ruled out because although pubic ramus fractures also occur after falls in osteoporotic patients and cause groin/hip pain, they do not typically cause the classic shortened, externally rotated leg deformity seen here.', 2),
('e8000000-0000-0000-0000-000000000013', 'C', 'Greater trochanteric bursitis', false, 'Ruled out because bursitis causes lateral hip pain, tenderness over the trochanter, and does not cause an acute deformity or inability to weight-bear after a fall.', 3),
('e8000000-0000-0000-0000-000000000013', 'D', 'Sciatica from lumbar disc prolapse', false, 'Ruled out because sciatica causes radicular leg pain with a normal hip examination and no limb deformity, not an acute shortened, externally rotated leg after a fall.', 4),
('e8000000-0000-0000-0000-000000000013', 'E', 'Fractured neck of femur', true, 'Correct. In an elderly patient with osteoporosis, a fall followed by inability to weight-bear, hip pain, and a shortened, externally rotated leg is the classic presentation of a fractured neck of femur, one of the most common and important fragility fractures in older adults.', 5),
('e8000000-0000-0000-0000-000000000014', 'A', 'Apply a backslab cast and discharge with outpatient fracture clinic follow-up', false, $x$Ruled out because a pale, cool hand with a weak pulse indicates vascular compromise, which is an emergency requiring urgent reduction, not simple splinting and outpatient follow-up, as delay risks limb ischaemia and Volkmann's contracture.$x$, 1),
('e8000000-0000-0000-0000-000000000014', 'B', 'Urgent orthopaedic referral for emergency reduction and fixation given signs of vascular compromise', true, 'Correct. A supracondylar fracture with a pale, cool hand and weak pulse indicates vascular compromise (often from brachial artery injury or kinking), which is a limb- and potentially life-threatening emergency in children requiring urgent reduction to restore perfusion, with close monitoring and surgical exploration if perfusion does not improve after reduction.', 2),
('e8000000-0000-0000-0000-000000000014', 'C', 'Reassure the family that reduced pulses are common and no action is needed', false, 'Ruled out because a weak pulse with a cool, pale hand in the context of a displaced supracondylar fracture is a vascular emergency requiring urgent intervention, not reassurance.', 3),
('e8000000-0000-0000-0000-000000000014', 'D', 'Arrange elective surgery in one week once swelling has settled', false, 'Ruled out because vascular compromise requires emergency, not elective delayed, intervention; waiting risks irreversible ischaemic damage to the forearm muscles and nerves.', 4),
('e8000000-0000-0000-0000-000000000014', 'E', 'Perform an angiogram before any reduction is attempted', false, 'Ruled out because in a pulseless or vascularly compromised supracondylar fracture, urgent closed reduction to restore alignment is the priority (often improving perfusion immediately); imaging should not delay emergency reduction.', 5),
('e8000000-0000-0000-0000-000000000015', 'A', $x$Smith's fracture$x$, false, $x$Ruled out because Smith's fracture is a volarly (palmar) displaced and angulated distal radius fracture, typically from a fall onto a flexed wrist, the opposite pattern to that described.$x$, 1),
('e8000000-0000-0000-0000-000000000015', 'B', $x$Bennett's fracture$x$, false, $x$Ruled out because Bennett's fracture is an intra-articular fracture at the base of the thumb metacarpal, not a distal radius fracture.$x$, 2),
('e8000000-0000-0000-0000-000000000015', 'C', $x$Colles' fracture$x$, true, $x$Correct. A Colles' fracture is a dorsally displaced and dorsally angulated fracture of the distal radius, classically occurring after a fall onto an outstretched hand (FOOSH), often with an associated ulnar styloid fracture.$x$, 3),
('e8000000-0000-0000-0000-000000000015', 'D', 'Galeazzi fracture', false, 'Ruled out because a Galeazzi fracture involves a distal radial shaft fracture with dislocation of the distal radioulnar joint, a different injury pattern to an isolated distal radius fracture with ulnar styloid involvement.', 4),
('e8000000-0000-0000-0000-000000000015', 'E', 'Monteggia fracture', false, 'Ruled out because a Monteggia fracture involves a proximal ulna fracture with dislocation of the radial head, not a distal radius fracture.', 5),
('e8000000-0000-0000-0000-000000000016', 'A', 'Immobilise the wrist in a scaphoid cast/splint and arrange repeat imaging (e.g. MRI or repeat radiographs) in 10-14 days', true, 'Correct. Scaphoid fractures are frequently not visible on initial radiographs; given the clinical suspicion (snuffbox tenderness after a FOOSH injury), the wrist should be immobilised presumptively and further imaging (MRI is most sensitive, or repeat radiographs at 10-14 days) arranged, because missed scaphoid fractures risk avascular necrosis of the scaphoid due to its precarious blood supply.', 1),
('e8000000-0000-0000-0000-000000000016', 'B', 'Discharge with reassurance as radiographs are normal', false, 'Ruled out because normal initial radiographs do not exclude a scaphoid fracture; missing this injury risks avascular necrosis and non-union, so clinical suspicion should prompt immobilisation and follow-up imaging rather than discharge.', 2),
('e8000000-0000-0000-0000-000000000016', 'C', 'Arrange elective outpatient physiotherapy without immobilisation', false, 'Ruled out because a suspected scaphoid fracture should be immobilised, not mobilised with physiotherapy, until the fracture is excluded or has healed, given the risk of avascular necrosis if missed and mobilised.', 3),
('e8000000-0000-0000-0000-000000000016', 'D', 'Perform an immediate open reduction and internal fixation', false, 'Ruled out because surgical fixation is not the immediate step for a suspected (not yet confirmed or displaced) scaphoid fracture; most undisplaced scaphoid fractures are managed with immobilisation, with surgery reserved for displaced or non-united fractures.', 4),
('e8000000-0000-0000-0000-000000000016', 'E', 'Administer a course of oral bisphosphonates', false, 'Ruled out because bisphosphonates treat osteoporosis, not an acute fracture, and are not relevant to the immediate management of a suspected scaphoid injury.', 5),
('e8000000-0000-0000-0000-000000000017', 'A', 'Pulmonary embolism from deep vein thrombosis', false, 'Ruled out because while VTE is an important differential after long bone fracture, it does not typically cause a petechial rash and confusion together with respiratory distress in this specific triad; the combination described is more characteristic of fat embolism syndrome.', 1),
('e8000000-0000-0000-0000-000000000017', 'B', 'Anaphylaxis to intravenous analgesia', false, 'Ruled out because anaphylaxis typically presents with urticaria, angioedema and hypotension shortly after drug exposure, not a petechial rash with confusion 24 hours after a fracture.', 2),
('e8000000-0000-0000-0000-000000000017', 'C', 'Fat embolism syndrome', true, 'Correct. Fat embolism syndrome classically occurs 24-72 hours after long bone (especially femoral) fracture, presenting with the triad of respiratory distress, neurological changes (confusion) and a petechial rash (classically over the chest, axillae and conjunctivae), caused by fat globules entering the circulation and lodging in the lungs and brain.', 3),
('e8000000-0000-0000-0000-000000000017', 'D', 'Acute exacerbation of undiagnosed asthma', false, 'Ruled out because asthma does not explain the petechial rash and confusion, and the timing/context (post-fracture) strongly suggests fat embolism syndrome.', 4),
('e8000000-0000-0000-0000-000000000017', 'E', 'Sepsis from an undiagnosed open wound', false, 'Ruled out because although sepsis can cause tachycardia and confusion, the specific petechial rash distribution and timing after long bone fracture, together with respiratory distress, are classic for fat embolism syndrome rather than sepsis.', 5),
('e8000000-0000-0000-0000-000000000018', 'A', 'Salter-Harris type I', false, 'Ruled out because type I fractures occur purely through the physis without extension into the metaphysis or epiphysis, which does not match the metaphyseal extension described.', 1),
('e8000000-0000-0000-0000-000000000018', 'B', 'Salter-Harris type III', false, 'Ruled out because type III fractures extend through the physis into the epiphysis (intra-articular), not the metaphysis as described here.', 2),
('e8000000-0000-0000-0000-000000000018', 'C', 'Salter-Harris type IV', false, 'Ruled out because type IV fractures extend through the epiphysis, physis and metaphysis (crossing all three), which is not what is described in this case.', 3),
('e8000000-0000-0000-0000-000000000018', 'D', 'Salter-Harris type II', true, 'Correct. Salter-Harris type II fractures extend through the physis and into the metaphysis, sparing the epiphysis; this is the most common type of growth plate fracture and generally has a good prognosis with appropriate management.', 4),
('e8000000-0000-0000-0000-000000000018', 'E', 'Salter-Harris type V', false, 'Ruled out because type V is a crush injury to the physis without an obvious fracture line, which is different from the clear fracture line extending into the metaphysis described here.', 5),
('e8000000-0000-0000-0000-000000000019', 'A', 'Reassure the patient that swelling after a fracture is normal and review in clinic in 2 weeks', false, 'Ruled out because increasing pain with reduced finger movement, discolouration and prolonged capillary refill are red flags for cast-related vascular compromise, not simply expected swelling, and require urgent action, not delayed review.', 1),
('e8000000-0000-0000-0000-000000000019', 'B', 'Increase the dose of oral analgesia and observe overnight without examining the limb', false, 'Ruled out because worsening pain and vascular signs in a casted limb should prompt urgent physical reassessment and cast loosening, not simply more analgesia without addressing the underlying cause.', 2),
('e8000000-0000-0000-0000-000000000019', 'C', 'Arrange an outpatient nerve conduction study', false, 'Ruled out because this does not address the acute, potentially limb-threatening issue of a tight cast; the immediate priority is urgent clinical reassessment and cast loosening, not deferred electrophysiological testing.', 3),
('e8000000-0000-0000-0000-000000000019', 'D', 'Advise the patient to keep the cast on and elevate the limb above heart level only', false, 'Ruled out because elevation alone will not relieve a tight cast causing compression, and the cast itself needs to be addressed urgently; over-elevation can also reduce perfusion pressure in evolving compartment syndrome.', 4),
('e8000000-0000-0000-0000-000000000019', 'E', 'Loosen or remove the cast urgently and reassess the limb', true, 'Correct. Increasing pain, swelling, discolouration and prolonged capillary refill in a limb in a cast raise concern for a tight cast causing vascular compromise or evolving compartment syndrome; the cast should be split/loosened or removed urgently and the limb reassessed, with escalation to orthopaedics if concerns persist.', 5),
('e8000000-0000-0000-0000-000000000020', 'A', 'Typical osteoporotic neck of femur fracture', false, 'Ruled out because a typical osteoporotic fracture occurs at the femoral neck with a shortened, externally rotated leg after a fall, not a subtrochanteric transverse fracture with cortical beaking associated with long-term bisphosphonate use.', 1),
('e8000000-0000-0000-0000-000000000020', 'B', 'Atypical femoral fracture associated with long-term bisphosphonate use', true, $x$Correct. Atypical femoral fractures are a recognised complication of long-term bisphosphonate therapy, presenting as transverse or short oblique fractures in the subtrochanteric or diaphyseal femur, often with minimal trauma, prodromal thigh pain, and characteristic lateral cortical thickening ('beaking') on imaging.$x$, 2),
('e8000000-0000-0000-0000-000000000020', 'C', 'Pathological fracture due to metastatic bone disease', false, 'Ruled out because although pathological fractures should always be considered, the specific transverse fracture pattern with lateral cortical beaking in a patient on long-term bisphosphonates is characteristic of an atypical femoral fracture rather than metastatic disease, though further work-up may still be warranted if doubt remains.', 3),
('e8000000-0000-0000-0000-000000000020', 'D', 'Stress fracture of the femoral shaft unrelated to medication', false, 'Ruled out because the clinical context (long-term bisphosphonate use, characteristic radiographic beaking, subtrochanteric location) specifically points to a bisphosphonate-associated atypical fracture rather than a generic stress fracture.', 4),
('e8000000-0000-0000-0000-000000000020', 'E', $x$Paget's disease of bone with pathological fracture$x$, false, $x$Ruled out because there is no mention of the radiographic features of Paget's disease (bone expansion, sclerosis, deformity), and the clinical context (long-term bisphosphonate therapy with classic beaking) points more specifically to an atypical femoral fracture.$x$, 5),
('e8000000-0000-0000-0000-000000000021', 'A', 'Posterior shoulder dislocation', false, 'Ruled out because posterior dislocation is much rarer, classically associated with seizures or electric shock, and typically presents with the arm held in adduction and internal rotation, not the abducted, externally rotated position and anterior fullness described here.', 1),
('e8000000-0000-0000-0000-000000000021', 'B', 'Anterior shoulder dislocation', true, $x$Correct. Anterior shoulder dislocation is the most common type of shoulder dislocation, typically resulting from a fall onto an abducted, externally rotated arm, presenting with loss of the normal shoulder contour ('squared-off' shoulder), a palpable anterior fullness, and severe pain with resistance to movement.$x$, 2),
('e8000000-0000-0000-0000-000000000021', 'C', 'Acromioclavicular joint dislocation', false, 'Ruled out because AC joint dislocation causes a step deformity at the top of the shoulder (distal clavicle) rather than the squared-off glenohumeral appearance and anterior fullness described, and the mechanism/position differs.', 3),
('e8000000-0000-0000-0000-000000000021', 'D', 'Clavicle fracture', false, 'Ruled out because a clavicle fracture typically causes localised tenderness and deformity over the clavicle itself, not the globally squared-off shoulder appearance with anterior fullness typical of glenohumeral dislocation.', 4),
('e8000000-0000-0000-0000-000000000021', 'E', 'Rotator cuff tear', false, 'Ruled out because an isolated rotator cuff tear causes weakness on specific movements without the gross deformity, squared-off appearance, and fixed abnormal position seen with a dislocation.', 5),
('e8000000-0000-0000-0000-000000000022', 'A', 'Posterior cruciate ligament (PCL) rupture', false, 'Ruled out because PCL injury typically presents with a positive posterior drawer test and often results from a direct blow to the front of a flexed knee (e.g. dashboard injury), not the pivoting mechanism with positive Lachman/anterior drawer described here.', 1),
('e8000000-0000-0000-0000-000000000022', 'B', 'Medial collateral ligament (MCL) sprain', false, 'Ruled out because MCL injury causes tenderness and laxity on valgus stress testing of the medial joint line, not positive anterior drawer/Lachman tests, which specifically indicate cruciate ligament laxity.', 2),
('e8000000-0000-0000-0000-000000000022', 'C', 'Anterior cruciate ligament (ACL) rupture', true, 'Correct. A pivoting/twisting injury with an audible pop, rapid haemarthrosis (swelling within hours) and positive Lachman and anterior drawer tests (indicating excessive anterior tibial translation) are classic features of an ACL rupture, one of the most common significant knee ligament injuries in sport.', 3),
('e8000000-0000-0000-0000-000000000022', 'D', 'Meniscal tear alone', false, 'Ruled out because although meniscal tears can cause joint line pain and sometimes a delayed effusion, the positive Lachman and anterior drawer tests specifically indicate ACL laxity; isolated meniscal tears do not cause this finding (though ACL tears often co-exist with meniscal injury).', 4),
('e8000000-0000-0000-0000-000000000022', 'E', 'Patellar dislocation', false, 'Ruled out because patellar dislocation typically presents with visible/palpable lateral displacement of the patella and apprehension on lateral patellar translation, not positive Lachman/anterior drawer tests.', 5),
('e8000000-0000-0000-0000-000000000023', 'A', 'Gastrocnemius muscle tear', false, 'Ruled out because although a gastrocnemius tear can cause acute calf pain during sport, it does not typically produce a palpable tendon gap or an absent response on the calf squeeze test, which specifically indicates loss of tendon continuity.', 1),
('e8000000-0000-0000-0000-000000000023', 'B', 'Deep vein thrombosis', false, 'Ruled out because DVT usually presents with gradual-onset calf swelling, warmth and tenderness rather than a sudden sharp pain during activity with a palpable gap and abnormal calf squeeze test.', 2),
('e8000000-0000-0000-0000-000000000023', 'C', 'Ankle sprain (lateral ligament injury)', false, 'Ruled out because ankle sprains cause pain and swelling around the lateral malleolus with ligament laxity, not a palpable gap in the Achilles tendon or an abnormal calf squeeze test.', 3),
('e8000000-0000-0000-0000-000000000023', 'D', 'Achilles tendon rupture', true, $x$Correct. A sudden sharp pain described as being 'kicked' in the calf during sport, a palpable tendon gap, and a positive Simmonds-Thompson calf squeeze test (absence of plantarflexion when the calf is squeezed) are classic features of an acute Achilles tendon rupture.$x$, 4),
('e8000000-0000-0000-0000-000000000023', 'E', 'Plantar fasciitis', false, 'Ruled out because plantar fasciitis causes gradual-onset heel pain, particularly with the first steps in the morning, not sudden acute calf pain with a tendon gap and abnormal calf squeeze test.', 5),
('e8000000-0000-0000-0000-000000000024', 'A', 'Glenohumeral joint dislocation', false, 'Ruled out because glenohumeral dislocation causes loss of the rounded shoulder contour and anterior/posterior fullness at the glenohumeral joint itself, not a step deformity localised to the distal clavicle/AC joint.', 1),
('e8000000-0000-0000-0000-000000000024', 'B', 'Clavicle midshaft fracture', false, 'Ruled out because a midshaft clavicle fracture causes tenderness and deformity in the middle of the clavicle, not a step deformity and joint widening localised to the acromioclavicular joint.', 2),
('e8000000-0000-0000-0000-000000000024', 'C', 'Sternoclavicular joint dislocation', false, 'Ruled out because sternoclavicular dislocation causes deformity and tenderness at the medial end of the clavicle near the sternum, not at the distal (lateral) end near the acromion.', 3),
('e8000000-0000-0000-0000-000000000024', 'D', 'Rotator cuff tendinopathy', false, 'Ruled out because tendinopathy causes pain on specific movements without a visible step deformity or radiographic joint widening/displacement.', 4),
('e8000000-0000-0000-0000-000000000024', 'E', 'Acromioclavicular joint (ACJ) dislocation/separation', true, 'Correct. A fall directly onto the shoulder causing a step deformity at the distal clavicle, with radiographic widening and superior displacement of the AC joint, is classic for acromioclavicular joint injury (commonly graded using the Rockwood classification).', 5),
('e8000000-0000-0000-0000-000000000025', 'A', 'No radiograph is required; manage as a soft tissue ankle sprain with rest, ice, compression, elevation and analgesia', true, 'Correct. According to the Ottawa Ankle Rules, an ankle radiograph is only required if there is bony tenderness at the posterior edge/tip of either malleolus, or inability to bear weight both immediately and in the emergency department for four steps. As this patient has no bony malleolar tenderness and can weight-bear for four steps, imaging is not required and this should be managed as a soft tissue lateral ligament sprain.', 1),
('e8000000-0000-0000-0000-000000000025', 'B', 'Arrange an urgent ankle radiograph before any further management', false, 'Ruled out because the Ottawa Ankle Rules criteria for imaging (bony malleolar tenderness or inability to weight-bear four steps) are not met in this patient, making a radiograph unnecessary.', 2),
('e8000000-0000-0000-0000-000000000025', 'C', 'Arrange an MRI of the ankle as first-line imaging', false, 'Ruled out because MRI is not first-line for an acute ankle sprain and is reserved for cases with ongoing symptoms or suspected significant ligamentous/osteochondral injury after initial assessment, not as an initial step here.', 3),
('e8000000-0000-0000-0000-000000000025', 'D', 'Immobilise the ankle in a rigid below-knee cast for 6 weeks', false, 'Ruled out because rigid immobilisation is not first-line for an uncomplicated lateral ligament sprain; functional treatment with early mobilisation and RICE principles is preferred and usually leads to better outcomes.', 4),
('e8000000-0000-0000-0000-000000000025', 'E', 'Refer immediately to orthopaedic surgery for consideration of ligament reconstruction', false, 'Ruled out because acute lateral ankle ligament sprains are managed conservatively in the vast majority of cases; surgical referral is not indicated as an initial step without a trial of conservative management.', 5),
('e8000000-0000-0000-0000-000000000026', 'A', 'Subacromial impingement syndrome (rotator cuff tendinopathy)', true, 'Correct. A painful arc of abduction between approximately 60-120 degrees, night pain, and pain with overhead activity, with preserved passive range of movement, is classic for subacromial impingement syndrome/rotator cuff tendinopathy, common in occupations involving repetitive overhead activity.', 1),
('e8000000-0000-0000-0000-000000000026', 'B', 'Adhesive capsulitis (frozen shoulder)', false, 'Ruled out because adhesive capsulitis characteristically causes global restriction of both active AND passive range of movement (especially external rotation), whereas this patient has full passive movement with only a painful arc, which is more typical of impingement.', 2),
('e8000000-0000-0000-0000-000000000026', 'C', 'Glenohumeral osteoarthritis', false, 'Ruled out because glenohumeral osteoarthritis typically causes progressive stiffness and reduced range of movement (including passive movement) with crepitus, rather than an isolated painful arc with full passive movement.', 3),
('e8000000-0000-0000-0000-000000000026', 'D', 'Acromioclavicular joint osteoarthritis', false, 'Ruled out because ACJ osteoarthritis typically causes localised pain at the top of the shoulder, worse with cross-body adduction, rather than a mid-range painful arc of abduction as the dominant feature.', 4),
('e8000000-0000-0000-0000-000000000026', 'E', 'Cervical radiculopathy', false, 'Ruled out because cervical radiculopathy causes neck pain with radiation and sensory/motor changes in a dermatomal/myotomal distribution, not an isolated painful arc of shoulder abduction with normal passive movement.', 5),
('e8000000-0000-0000-0000-000000000027', 'A', 'Radial nerve', false, 'Ruled out because radial nerve injury causes wrist drop and sensory loss over the dorsum of the hand/first web space, not weakness of shoulder abduction or regimental badge sensory loss.', 1),
('e8000000-0000-0000-0000-000000000027', 'B', 'Musculocutaneous nerve', false, 'Ruled out because musculocutaneous nerve injury causes weakness of elbow flexion (biceps/brachialis) and sensory loss over the lateral forearm, not shoulder abduction weakness or regimental badge sensory loss.', 2),
('e8000000-0000-0000-0000-000000000027', 'C', 'Ulnar nerve', false, 'Ruled out because ulnar nerve injury causes weakness of intrinsic hand muscles and sensory loss over the little finger/ulnar half of the ring finger, unrelated to shoulder abduction or the regimental badge area.', 3),
('e8000000-0000-0000-0000-000000000027', 'D', 'Axillary nerve', true, $x$Correct. The axillary nerve is the nerve most commonly injured in anterior shoulder dislocation due to its close proximity to the inferior glenohumeral joint capsule; injury causes weakness of shoulder abduction (deltoid) and sensory loss over the 'regimental badge' area of the lateral upper arm.$x$, 4),
('e8000000-0000-0000-0000-000000000027', 'E', 'Suprascapular nerve', false, 'Ruled out because suprascapular nerve injury affects supraspinatus and infraspinatus (abduction initiation and external rotation) without the specific regimental badge sensory loss pattern, which is characteristic of axillary nerve injury.', 5),
('e8000000-0000-0000-0000-000000000028', 'A', $x$Medial epicondylitis ('golfer's elbow')$x$, false, 'Ruled out because medial epicondylitis causes pain over the medial epicondyle, reproduced by resisted wrist flexion, not the lateral-sided pain reproduced by resisted extension described here.', 1),
('e8000000-0000-0000-0000-000000000028', 'B', $x$Lateral epicondylitis ('tennis elbow')$x$, true, 'Correct. Pain over the lateral epicondyle reproduced by resisted wrist extension, associated with repetitive gripping/extension activities, is the classic presentation of lateral epicondylitis, an overuse tendinopathy of the common extensor origin.', 2),
('e8000000-0000-0000-0000-000000000028', 'C', 'Olecranon bursitis', false, 'Ruled out because olecranon bursitis presents with swelling directly over the olecranon (posterior elbow), not lateral elbow pain reproduced by resisted wrist extension.', 3),
('e8000000-0000-0000-0000-000000000028', 'D', 'Ulnar nerve entrapment at the elbow (cubital tunnel syndrome)', false, 'Ruled out because cubital tunnel syndrome causes sensory disturbance in the ulnar nerve distribution (little and ring fingers) and possible hand weakness, not isolated lateral epicondylar tenderness reproduced by resisted extension.', 4),
('e8000000-0000-0000-0000-000000000028', 'E', 'Radial head fracture', false, 'Ruled out because a fracture would typically follow an acute traumatic event with swelling and restricted movement, not a gradual 6-week history related to repetitive activity.', 5),
('e8000000-0000-0000-0000-000000000029', 'A', 'Reassure the patient and arrange elective vascular review in outpatient clinic', false, 'Ruled out because an absent pulse with a cool, pale, poorly sensate foot after knee dislocation indicates a limb-threatening vascular injury requiring emergency, not elective, assessment.', 1),
('e8000000-0000-0000-0000-000000000029', 'B', 'Apply a tourniquet to the thigh and observe', false, 'Ruled out because a tourniquet would worsen distal ischaemia in a limb already lacking arterial inflow and is not appropriate management for suspected popliteal artery injury without active life-threatening haemorrhage.', 2),
('e8000000-0000-0000-0000-000000000029', 'C', 'Discharge home with crutches and analgesia, advising GP follow-up', false, 'Ruled out because this represents a vascular emergency with limb-threatening ischaemia that requires immediate hospital-based intervention, not discharge.', 3),
('e8000000-0000-0000-0000-000000000029', 'D', 'Arrange an MRI of the knee as the first investigation before any other action', false, 'Ruled out because in the presence of hard signs of vascular injury (absent pulse, pale/cool limb), urgent vascular imaging (e.g. CT angiography) and surgical referral should proceed without delay; MRI of the ligaments is not the priority and would dangerously delay limb-salvage intervention.', 4),
('e8000000-0000-0000-0000-000000000029', 'E', 'Urgent vascular surgical referral for assessment of popliteal artery injury, alongside orthopaedic input', true, 'Correct. Knee dislocation (even if spontaneously reduced) carries a high risk of popliteal artery injury due to its fixed course behind the knee; an absent pulse with a cool, pale foot indicates an arterial injury requiring emergency vascular assessment and likely intervention to prevent limb loss, alongside orthopaedic management of the unstable joint.', 5),
('e8000000-0000-0000-0000-000000000030', 'A', 'ACL rupture', false, 'Ruled out because ligament stability tests (which would be abnormal in ACL rupture, e.g. positive Lachman/anterior drawer) are specifically stated to be normal here, making isolated meniscal injury more likely.', 1),
('e8000000-0000-0000-0000-000000000030', 'B', 'MCL sprain', false, $x$Ruled out because MCL injury would show laxity on valgus stress testing, which is not described; the positive McMurray's test specifically points to meniscal pathology rather than collateral ligament injury.$x$, 2),
('e8000000-0000-0000-0000-000000000030', 'C', 'Medial meniscal tear', true, $x$Correct. A twisting knee injury with medial joint line tenderness, effusion, and a positive McMurray's test (pain/click on flexion and external rotation localising to the medial joint line) with normal ligament stability testing is classic for a medial meniscal tear, one of the most common significant knee injuries in sport.$x$, 3),
('e8000000-0000-0000-0000-000000000030', 'D', 'Patellar tendon rupture', false, $x$Ruled out because patellar tendon rupture causes inability to actively extend the knee and a palpable gap above the patella, not joint line tenderness with a positive McMurray's test.$x$, 4),
('e8000000-0000-0000-0000-000000000030', 'E', 'Osteochondritis dissecans', false, $x$Ruled out because this is typically a more insidious, chronic condition in adolescents rather than an acute injury with a clear traumatic twisting mechanism and positive McMurray's test.$x$, 5),
('e8000000-0000-0000-0000-000000000031', 'A', 'Start oral antibiotics and review in outpatient clinic in one week', false, 'Ruled out because septic arthritis is a medical emergency requiring urgent admission, joint aspiration and IV antibiotics, not oral antibiotics with delayed outpatient review, given the risk of rapid joint destruction and sepsis.', 1),
('e8000000-0000-0000-0000-000000000031', 'B', 'Arrange an MRI of the knee as the first step before any other intervention', false, 'Ruled out because while imaging may have a role, the priority in suspected septic arthritis is urgent joint aspiration and starting antibiotics without delay; imaging should not delay these emergency steps.', 2),
('e8000000-0000-0000-0000-000000000031', 'C', 'Apply ice and compression and reassess in 48 hours', false, 'Ruled out because this significantly delays diagnosis and treatment of a suspected joint infection, which requires urgent same-day assessment and intervention, not a delayed reassessment.', 3),
('e8000000-0000-0000-0000-000000000031', 'D', 'Urgent joint aspiration for synovial fluid analysis and culture, before starting empirical intravenous antibiotics', true, 'Correct. Suspected septic arthritis is an emergency; the joint should be aspirated urgently (ideally before antibiotics, unless this would cause significant delay) to obtain fluid for Gram stain, culture and crystal analysis, and empirical IV antibiotics should be started promptly according to local protocols, as delayed treatment risks rapid joint destruction and systemic sepsis.', 4),
('e8000000-0000-0000-0000-000000000031', 'E', 'Give a single dose of intra-articular corticosteroid to reduce inflammation', false, 'Ruled out because intra-articular steroids are contraindicated in suspected septic arthritis, as they can worsen the infection and mask clinical signs; this is a dangerous action in this context.', 5),
('e8000000-0000-0000-0000-000000000032', 'A', 'Septic arthritis', false, 'Ruled out because septic arthritis would typically show organisms on Gram stain or a positive culture from an infected joint; here the joint fluid is culture-negative, and the temporal relationship to a preceding GI infection with additional extra-articular features favours reactive arthritis.', 1),
('e8000000-0000-0000-0000-000000000032', 'B', 'Gout', false, 'Ruled out because gout is caused by monosodium urate crystal deposition, which would be seen on polarised light microscopy of synovial fluid, not associated with a preceding diarrhoeal illness and conjunctivitis/dysuria.', 2),
('e8000000-0000-0000-0000-000000000032', 'C', 'Reactive arthritis', true, 'Correct. Reactive arthritis is a sterile inflammatory arthritis triggered by a preceding gastrointestinal (e.g. Campylobacter, Salmonella, Shigella) or genitourinary (e.g. Chlamydia) infection, typically occurring 1-4 weeks afterward, classically associated with the triad of arthritis, conjunctivitis and urethritis; synovial fluid is inflammatory but culture-negative, distinguishing it from septic arthritis.', 3),
('e8000000-0000-0000-0000-000000000032', 'D', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis typically causes a chronic, symmetrical small joint polyarthritis rather than an acute monoarthritis temporally linked to a preceding gastrointestinal infection with conjunctivitis and dysuria.', 4),
('e8000000-0000-0000-0000-000000000032', 'E', 'Gonococcal septic arthritis', false, 'Ruled out because although gonococcal arthritis can present with similar joint symptoms, the negative culture and clear temporal association with a confirmed Campylobacter gastroenteritis, plus conjunctivitis, is more consistent with reactive arthritis than gonococcal infection.', 5),
('e8000000-0000-0000-0000-000000000033', 'A', 'Acute osteomyelitis', true, 'Correct. Fever, localised bone pain/tenderness/swelling and refusal to weight-bear in a child, with raised inflammatory markers, is classic for acute haematogenous osteomyelitis, most commonly affecting the metaphysis of long bones (e.g. distal femur, proximal tibia); plain radiographs are often normal in the early stages, and MRI is the investigation of choice.', 1),
('e8000000-0000-0000-0000-000000000033', 'B', 'Septic arthritis of the knee', false, 'Ruled out because the tenderness and swelling are localised to the distal femur (bone) rather than the joint line itself; while septic arthritis is an important differential and can coexist, the description here is more specific to bone involvement, consistent with osteomyelitis.', 2),
('e8000000-0000-0000-0000-000000000033', 'C', 'Transient synovitis (irritable hip)', false, 'Ruled out because transient synovitis classically affects the hip in a well-looking child with mild or no fever and normal/mildly raised inflammatory markers, not marked fever with significantly raised inflammatory markers and focal bone tenderness.', 3),
('e8000000-0000-0000-0000-000000000033', 'D', 'Juvenile idiopathic arthritis', false, 'Ruled out because JIA typically presents with a more insidious onset of joint swelling/stiffness over weeks, not an acute 3-day history with high fever and focal bone tenderness, which is more consistent with an acute infective process.', 4),
('e8000000-0000-0000-0000-000000000033', 'E', 'Growing pains', false, 'Ruled out because growing pains are typically bilateral, occur at night, and are not associated with fever, focal tenderness, swelling or raised inflammatory markers.', 5),
('e8000000-0000-0000-0000-000000000034', 'A', 'Aseptic loosening only, with infection excluded by the clinical picture', false, 'Ruled out because infection cannot be excluded on clinical grounds alone; the presence of intermittent fevers and elevated inflammatory markers means chronic infection must be actively investigated (e.g. joint aspiration) alongside considering aseptic loosening as a differential.', 1),
('e8000000-0000-0000-0000-000000000034', 'B', 'Simple osteoarthritis flare in the native contralateral knee', false, 'Ruled out because the symptoms are localised to the previously replaced knee with systemic features (fever, raised inflammatory markers), which point away from a straightforward osteoarthritis flare and toward possible infection.', 2),
('e8000000-0000-0000-0000-000000000034', 'C', 'Gout affecting the prosthetic joint', false, 'Ruled out because although gout can occur in a joint with a prosthesis, the gradual six-week course with intermittent fevers is more suggestive of chronic infection, which must be actively excluded before considering less likely diagnoses.', 3),
('e8000000-0000-0000-0000-000000000034', 'D', 'Referred pain from lumbar spinal stenosis', false, 'Ruled out because localised knee findings with systemic inflammatory features point to a knee-specific pathology (chronic prosthetic infection) rather than referred spinal pain.', 4),
('e8000000-0000-0000-0000-000000000034', 'E', 'Chronic (low-grade) prosthetic joint infection', true, 'Correct. A subacute, gradually worsening presentation of joint pain with intermittent low-grade fevers and mildly elevated inflammatory markers several years after joint replacement is consistent with chronic, low-virulence prosthetic joint infection (e.g. coagulase-negative staphylococci), which can present more indolently than acute post-operative infection and requires specialist investigation (joint aspiration, imaging) rather than being dismissed.', 5),
('e8000000-0000-0000-0000-000000000035', 'A', 'Discharge with oral antibiotics and outpatient physiotherapy', false, 'Ruled out because vertebral osteomyelitis with an epidural abscess is a serious infection with risk of neurological compromise requiring urgent inpatient specialist management, not discharge with oral antibiotics alone.', 1),
('e8000000-0000-0000-0000-000000000035', 'B', 'Urgent referral to spinal surgery/microbiology for assessment, blood cultures, and consideration of drainage plus targeted intravenous antibiotics', true, 'Correct. Vertebral osteomyelitis with an associated epidural abscess is a serious infection with risk of spinal cord compression and neurological deterioration; urgent multidisciplinary assessment (spinal surgery, microbiology/infectious diseases) is required, with blood cultures taken before antibiotics where possible, and consideration of surgical drainage alongside prolonged targeted IV antibiotics.', 2),
('e8000000-0000-0000-0000-000000000035', 'C', 'Arrange elective outpatient MRI in 6 weeks to monitor progression', false, 'Ruled out because the diagnosis has already been confirmed on MRI and represents an urgent condition requiring immediate action, not delayed monitoring.', 3),
('e8000000-0000-0000-0000-000000000035', 'D', 'Administer a single dose of intramuscular antibiotics and reassess in one week', false, 'Ruled out because vertebral osteomyelitis with epidural abscess requires prolonged targeted intravenous antibiotic therapy (often weeks), guided by cultures, alongside specialist and potentially surgical input, not a single intramuscular dose.', 4),
('e8000000-0000-0000-0000-000000000035', 'E', 'Perform urgent lumbar puncture to confirm the diagnosis before any other action', false, 'Ruled out because lumbar puncture is not required to confirm this diagnosis (already made on MRI) and could be hazardous near a spinal infection/epidural collection; the priority is specialist referral, cultures and targeted treatment planning.', 5),
('e8000000-0000-0000-0000-000000000036', 'A', 'Staphylococcus aureus', false, 'Ruled out because although S. aureus is the most common overall cause of septic arthritis, the specific combination of tenosynovitis, pustular skin lesions and recent sexual exposure is much more characteristic of disseminated gonococcal infection than staphylococcal infection.', 1),
('e8000000-0000-0000-0000-000000000036', 'B', 'Streptococcus pyogenes', false, 'Ruled out because this organism does not typically cause the specific triad of tenosynovitis, dermatitis and sexual exposure history seen in disseminated gonococcal infection.', 2),
('e8000000-0000-0000-0000-000000000036', 'C', 'Escherichia coli', false, 'Ruled out because E. coli septic arthritis is uncommon and not associated with the classic gonococcal triad of tenosynovitis, dermatitis and recent sexual exposure.', 3),
('e8000000-0000-0000-0000-000000000036', 'D', 'Mycobacterium tuberculosis', false, 'Ruled out because TB arthritis typically has a more chronic, indolent course rather than an acute 2-day presentation with the specific gonococcal triad described here.', 4),
('e8000000-0000-0000-0000-000000000036', 'E', 'Neisseria gonorrhoeae', true, 'Correct. The triad of migratory polyarthralgia/tenosynovitis, dermatitis (pustular/vesicular skin lesions) and a history of recent sexual exposure is classic for disseminated gonococcal infection, which can cause an acute septic monoarthritis; N. gonorrhoeae is an important cause of septic arthritis in sexually active young adults.', 5),
('e8000000-0000-0000-0000-000000000037', 'A', 'Increase the dose of prednisolone to treat a presumed rheumatoid flare', false, 'Ruled out because increasing immunosuppression without first excluding infection could be dangerous if this represents septic arthritis, worsening outcomes; infection must be excluded first.', 1),
('e8000000-0000-0000-0000-000000000037', 'B', 'Continue methotrexate and reassess symptoms in 2 weeks', false, 'Ruled out because this delays urgent assessment of a potentially serious joint infection in an immunosuppressed patient, risking rapid deterioration.', 2),
('e8000000-0000-0000-0000-000000000037', 'C', 'Arrange outpatient rheumatology review within the next month', false, 'Ruled out because an acutely hot, swollen joint with fever and unusually high CRP in an immunosuppressed patient needs same-day urgent assessment (including joint aspiration), not delayed outpatient review.', 3),
('e8000000-0000-0000-0000-000000000037', 'D', 'Urgent joint aspiration to exclude septic arthritis before assuming this is a rheumatoid flare', true, 'Correct. Patients with rheumatoid arthritis on immunosuppressive therapy are at increased risk of septic arthritis, which can mimic a disease flare; any acute joint presentation in this context, especially with unusually high inflammatory markers or examination findings, must have septic arthritis actively excluded by urgent joint aspiration before attributing symptoms to a flare, as missed infection can be catastrophic.', 4),
('e8000000-0000-0000-0000-000000000037', 'E', 'Start empirical antifungal therapy immediately without further assessment', false, 'Ruled out because there is no specific indication for fungal infection here; the priority is urgent joint aspiration to identify the causative organism, which is far more likely to be bacterial, before choosing empirical therapy.', 5),
('e8000000-0000-0000-0000-000000000038', 'A', 'Simple cellulitis without bone involvement', false, 'Ruled out because a positive probe-to-bone test combined with radiographic cortical destruction specifically indicates bone involvement (osteomyelitis), not just soft tissue cellulitis.', 1),
('e8000000-0000-0000-0000-000000000038', 'B', 'Charcot neuroarthropathy', false, 'Ruled out because Charcot neuroarthropathy typically presents with a warm, swollen, sometimes deformed foot due to neuropathic joint destruction, usually without an overlying chronic ulcer probing to bone with cortical destruction at a discrete site as described here, although the two conditions can coexist and be difficult to distinguish.', 2),
('e8000000-0000-0000-0000-000000000038', 'C', 'Osteomyelitis of the underlying metatarsal', true, $x$Correct. A chronic diabetic foot ulcer with a positive 'probe-to-bone' test (probe reaching bone) and radiographic cortical destruction/periosteal reaction is highly suggestive of underlying osteomyelitis, a common and serious complication of diabetic foot disease requiring prompt specialist multidisciplinary management.$x$, 3),
('e8000000-0000-0000-0000-000000000038', 'D', 'Peripheral arterial disease with critical limb ischaemia', false, 'Ruled out because while PAD is an important contributing factor in diabetic foot disease and should be assessed, the specific findings described (probe to bone, cortical destruction, periosteal reaction) point specifically to osteomyelitis rather than ischaemia alone.', 4),
('e8000000-0000-0000-0000-000000000038', 'E', 'Gout affecting the metatarsal joint', false, 'Ruled out because gout causes acute joint inflammation from urate crystal deposition, not a chronic ulcer with a probe reaching bone and periosteal reaction on imaging.', 5),
('e8000000-0000-0000-0000-000000000039', 'A', 'Transient synovitis (irritable hip)', true, 'Correct. Transient synovitis is the most common cause of acute hip pain and limp in young children, often following a recent viral infection, typically presenting with a well child, mild or no fever, and only mildly elevated inflammatory markers, distinguishing it from septic arthritis, which usually causes a more unwell child with higher fever and significantly raised inflammatory markers.', 1),
('e8000000-0000-0000-0000-000000000039', 'B', 'Septic arthritis of the hip', false, 'Ruled out because septic arthritis typically presents with a more unwell, febrile child, inability to weight-bear, and significantly elevated inflammatory markers, which are not consistent with this well-looking child with only mild elevation of markers, although septic arthritis must always remain a key differential to actively exclude.', 2),
('e8000000-0000-0000-0000-000000000039', 'C', $x$Perthes' disease$x$, false, $x$Ruled out because Perthes' disease (avascular necrosis of the femoral head) typically affects slightly older children (4-8 years) with a more insidious, chronic history rather than an acute 2-day onset following a viral illness.$x$, 3),
('e8000000-0000-0000-0000-000000000039', 'D', 'Slipped upper femoral epiphysis (SUFE)', false, 'Ruled out because SUFE typically occurs in older children/adolescents (often overweight boys aged 10-15), not a 3-year-old, and presents with hip/groin/knee pain and an externally rotated leg rather than this acute post-viral presentation.', 4),
('e8000000-0000-0000-0000-000000000039', 'E', 'Juvenile idiopathic arthritis', false, 'Ruled out because JIA typically has a more chronic, insidious course over weeks and is not classically triggered by a recent viral illness with this acute 2-day presentation.', 5),
('e8000000-0000-0000-0000-000000000040', 'A', 'A single 7-day course of oral antibiotics', false, 'Ruled out because vertebral osteomyelitis/discitis requires a much longer duration of therapy (typically weeks, not days) due to the difficulty of eradicating infection from bone; a short course risks treatment failure and relapse.', 1),
('e8000000-0000-0000-0000-000000000040', 'B', 'Prolonged targeted intravenous antibiotics (typically at least 6 weeks), guided by microbiology advice and clinical/inflammatory marker response', true, 'Correct. Vertebral discitis/osteomyelitis, particularly due to Staphylococcus aureus, requires a prolonged course of targeted antibiotics (commonly a minimum of around 6 weeks, often starting intravenously) guided by microbiology and infectious diseases input, with monitoring of clinical response and inflammatory markers, due to the difficulty of achieving adequate antibiotic penetration into bone and the risk of relapse or progression to abscess/instability if under-treated.', 2),
('e8000000-0000-0000-0000-000000000040', 'C', 'No antibiotics are needed as there is no epidural abscess or neurological deficit', false, 'Ruled out because confirmed vertebral osteomyelitis/discitis with positive blood cultures requires antibiotic treatment regardless of the absence of abscess or neurological deficit, to eradicate infection and prevent progression.', 3),
('e8000000-0000-0000-0000-000000000040', 'D', 'Immediate surgical fixation of the spine without antibiotics', false, 'Ruled out because surgery is not the primary treatment for uncomplicated discitis/osteomyelitis without abscess, cord compression or instability; the mainstay of treatment is prolonged targeted antibiotic therapy, with surgery reserved for specific complications.', 4),
('e8000000-0000-0000-0000-000000000040', 'E', 'Topical antiseptic dressings to the overlying skin only', false, 'Ruled out because this is a deep bone/disc space infection confirmed on blood culture and MRI, requiring systemic antibiotic therapy, not topical skin treatment, which would not address the underlying infection at all.', 5),
('e8000000-0000-0000-0000-000000000041', 'A', 'Prescribe oral analgesia and review in the GP surgery in one week', false, 'Ruled out because the presence of saddle anaesthesia, bladder dysfunction and reduced anal tone are red flags for cauda equina syndrome, requiring same-day emergency referral, not routine delayed review.', 1),
('e8000000-0000-0000-0000-000000000041', 'B', 'Emergency referral for same-day MRI of the whole spine and urgent neurosurgical/spinal assessment', true, 'Correct. Bilateral leg pain, saddle (perineal) anaesthesia, bladder dysfunction (urinary retention/difficulty voiding) and reduced anal tone are red flag features of cauda equina syndrome, a surgical emergency requiring same-day MRI and urgent spinal/neurosurgical assessment for potential decompression, as delay risks permanent neurological damage including incontinence and paralysis.', 2),
('e8000000-0000-0000-0000-000000000041', 'C', 'Refer routinely to musculoskeletal physiotherapy', false, 'Ruled out because red flag features (saddle anaesthesia, bladder dysfunction, reduced anal tone) mandate emergency same-day referral for imaging and specialist assessment, not routine physiotherapy referral, which risks catastrophic delay.', 3),
('e8000000-0000-0000-0000-000000000041', 'D', 'Arrange an outpatient MRI within the next 2 weeks', false, 'Ruled out because cauda equina syndrome is a surgical emergency requiring same-day MRI, not an outpatient scan scheduled weeks later, as any delay risks permanent neurological deficit.', 4),
('e8000000-0000-0000-0000-000000000041', 'E', 'Reassure the patient that this is likely simple mechanical back pain and advise rest', false, 'Ruled out because the described features (bilateral leg pain, saddle anaesthesia, bladder dysfunction, reduced anal tone) are classic red flags for cauda equina syndrome, not simple mechanical back pain, and require emergency assessment.', 5),
('e8000000-0000-0000-0000-000000000042', 'A', 'Complete spinal cord injury', false, 'Ruled out because a complete injury, by definition (ASIA A), would show no motor or sensory function in the sacral segments (S4-S5), including no voluntary anal contraction and no perianal sensation; the presence of these findings specifically indicates an incomplete injury.', 1),
('e8000000-0000-0000-0000-000000000042', 'B', 'Cauda equina syndrome', false, 'Ruled out because this is a spinal cord level injury given the described sensory level at T4, a higher level than the cauda equina (which begins around L1-L2); the pattern described reflects cord, not cauda equina, injury.', 2),
('e8000000-0000-0000-0000-000000000042', 'C', 'Peripheral nerve injury', false, 'Ruled out because the pattern of a discrete sensory level (T4) with widespread bilateral motor/sensory loss below that level is consistent with spinal cord injury, not an isolated peripheral nerve lesion.', 3),
('e8000000-0000-0000-0000-000000000042', 'D', 'Incomplete spinal cord injury (evidenced by sacral sparing)', true, $x$Correct. The presence of preserved anal sensation and voluntary anal contraction, despite loss of motor/sensory function elsewhere below the level of injury, indicates 'sacral sparing', which by definition means the injury is incomplete; this has important prognostic implications as some incomplete injuries can show further neurological recovery.$x$, 4),
('e8000000-0000-0000-0000-000000000042', 'E', 'Spinal shock resolving normally', false, 'Ruled out because although spinal shock (transient loss of reflexes below the injury level) can occur after acute spinal cord injury, sacral sparing specifically defines the injury as neurologically incomplete rather than simply describing a physiological resolving process.', 5),
('e8000000-0000-0000-0000-000000000043', 'A', 'Arrange an urgent MRI of the lumbar spine', false, 'Ruled out because in the absence of red flag features, routine imaging is not required for simple mechanical back pain and does not change initial management; imaging is reserved for cases with red flags or that fail to improve with conservative treatment.', 1),
('e8000000-0000-0000-0000-000000000043', 'B', 'Prescribe strict bed rest for 2 weeks', false, 'Ruled out because prolonged bed rest is not recommended for mechanical back pain and can worsen outcomes; patients are advised to stay as active as possible.', 2),
('e8000000-0000-0000-0000-000000000043', 'C', 'Refer immediately for urgent spinal surgical assessment', false, 'Ruled out because there are no red flag features suggesting a surgical emergency (e.g. cauda equina syndrome) or an indication for surgical referral at this stage; conservative management is appropriate first.', 3),
('e8000000-0000-0000-0000-000000000043', 'D', 'Start long-term high-dose opioid therapy', false, 'Ruled out because opioids are not first-line or recommended for long-term management of non-specific back pain, given limited efficacy and risk of dependence; simple analgesia and staying active are preferred.', 4),
('e8000000-0000-0000-0000-000000000043', 'E', 'Advise the patient to stay active, use simple analgesia, and reassure that this is likely simple mechanical (non-specific) back pain that typically improves within a few weeks', true, 'Correct. In the absence of any red flag features (no fever, weight loss, night pain, saddle anaesthesia, bladder/bowel dysfunction, or progressive neurological deficit), this presentation is consistent with simple mechanical low back pain, which is managed conservatively with advice to remain active, simple analgesia, and reassurance, without the need for urgent imaging.', 5),
('e8000000-0000-0000-0000-000000000044', 'A', 'Osteoporotic vertebral compression fracture', true, 'Correct. Sudden severe back pain after a trivial mechanical movement (such as bending) in a patient with known osteoporosis, associated with height loss over time and localised spinal tenderness without neurological deficit, is classic for an osteoporotic vertebral compression fracture, a common fragility fracture.', 1),
('e8000000-0000-0000-0000-000000000044', 'B', 'Cauda equina syndrome', false, 'Ruled out because there are no red flag features such as saddle anaesthesia, bladder/bowel dysfunction, bilateral leg pain or neurological deficit, making cauda equina syndrome unlikely; the presentation is localised spinal pain consistent with a compression fracture.', 2),
('e8000000-0000-0000-0000-000000000044', 'C', 'Metastatic spinal cord compression', false, 'Ruled out because although malignancy should always be considered in back pain in older patients, the clear context of known osteoporosis, height loss, and a trivial precipitating movement without neurological deficit makes an osteoporotic fragility fracture far more likely; however, red flags for malignancy should still be screened for.', 3),
('e8000000-0000-0000-0000-000000000044', 'D', 'Spinal epidural abscess', false, 'Ruled out because there are no features of infection (fever, risk factors such as IV drug use, raised inflammatory markers) described, making an abscess unlikely compared with an osteoporotic fracture in this context.', 4),
('e8000000-0000-0000-0000-000000000044', 'E', 'Mechanical facet joint back pain', false, 'Ruled out because facet joint pain does not typically cause sudden severe pain after a trivial movement with progressive height loss over years; the clinical picture here is much more specific for vertebral fragility fracture.', 5),
('e8000000-0000-0000-0000-000000000045', 'A', 'Remove the cervical collar immediately since the patient has a normal GCS', false, 'Ruled out because a normal GCS does not exclude a cervical spine fracture; midline tenderness after a high-risk mechanism (diving injury) mandates continued immobilisation until imaging has excluded significant injury.', 1),
('e8000000-0000-0000-0000-000000000045', 'B', 'Perform active range of motion testing of the neck to assess for injury', false, 'Ruled out because actively moving the neck in a patient with midline tenderness after a high-risk mechanism risks worsening a potential unstable spinal injury and should not be performed before imaging.', 2),
('e8000000-0000-0000-0000-000000000045', 'C', 'Maintain full spinal immobilisation and arrange urgent cervical spine imaging (CT) before any clearance of the spine', true, 'Correct. This is a high-risk mechanism (axial loading diving injury) with midline cervical tenderness, so spinal immobilisation must be maintained until the cervical spine has been appropriately imaged (CT is the first-line imaging modality in adults with high-risk features) and cleared by an appropriately trained clinician; premature removal of precautions risks catastrophic spinal cord injury if an unstable fracture is present.', 3),
('e8000000-0000-0000-0000-000000000045', 'D', 'Discharge with advice to rest and take over-the-counter analgesia', false, 'Ruled out because midline cervical spine tenderness after a high-risk diving mechanism requires imaging to exclude fracture before any consideration of discharge; this would be unsafe.', 4),
('e8000000-0000-0000-0000-000000000045', 'E', 'Arrange a plain cervical spine radiograph only, without CT', false, 'Ruled out because current major trauma guidance recommends CT (not plain radiographs) as first-line imaging for suspected cervical spine injury in adults with high-risk mechanisms or clinical features, due to higher sensitivity for detecting fractures.', 5),
('e8000000-0000-0000-0000-000000000046', 'A', 'Arrange routine outpatient MRI in the next available slot within a few weeks', false, 'Ruled out because suspected metastatic spinal cord compression is an oncological emergency requiring same-day imaging and assessment, not a routine outpatient appointment weeks later, given the risk of rapid, irreversible neurological deterioration.', 1),
('e8000000-0000-0000-0000-000000000046', 'B', 'Reassure the patient that this is likely mechanical back pain given her age', false, 'Ruled out because the combination of a history of malignancy, night pain, progressive leg weakness, bladder dysfunction and weight loss are all red flags requiring urgent same-day investigation, not reassurance.', 2),
('e8000000-0000-0000-0000-000000000046', 'C', 'Refer for physiotherapy for symptomatic relief', false, 'Ruled out because red flag features strongly suggest a serious underlying pathology (metastatic spinal cord compression) requiring emergency same-day assessment, not conservative physiotherapy referral.', 3),
('e8000000-0000-0000-0000-000000000046', 'D', 'Start a course of oral NSAIDs and review in 2 weeks', false, 'Ruled out because this significantly delays urgent investigation and treatment of a likely oncological emergency, risking permanent neurological damage in the interim.', 4),
('e8000000-0000-0000-0000-000000000046', 'E', 'Emergency referral for same-day MRI of the whole spine and urgent oncology/spinal assessment for suspected metastatic spinal cord compression', true, 'Correct. A history of previous malignancy with new back pain that is worse at night/at rest, progressive bilateral leg weakness, bladder dysfunction and unintentional weight loss are classic red flags for metastatic spinal cord compression, an oncological emergency requiring same-day MRI of the whole spine and urgent specialist assessment (often including high-dose corticosteroids while awaiting definitive treatment), as delay risks permanent paralysis.', 5),
('e8000000-0000-0000-0000-000000000047', 'A', 'Mechanical low back pain', false, 'Ruled out because mechanical back pain typically worsens with activity and improves with rest, the opposite pattern to the inflammatory picture described (morning stiffness improving with exercise), and does not explain the associated uveitis or reduced chest expansion.', 1),
('e8000000-0000-0000-0000-000000000047', 'B', 'Ankylosing spondylitis (axial spondyloarthritis)', true, 'Correct. Inflammatory back pain with morning stiffness improving with exercise, alternating buttock pain (from sacroiliitis), reduced spinal flexion and chest expansion, and a history of anterior uveitis, in a young adult, is classic for ankylosing spondylitis/axial spondyloarthritis, a seronegative spondyloarthropathy.', 2),
('e8000000-0000-0000-0000-000000000047', 'C', 'Lumbar disc herniation', false, 'Ruled out because disc herniation typically causes acute or subacute radicular leg pain following a specific mechanical trigger, not an 8-month history of inflammatory-pattern back stiffness with alternating buttock pain and extra-articular uveitis.', 3),
('e8000000-0000-0000-0000-000000000047', 'D', 'Osteoarthritis of the lumbar facet joints', false, 'Ruled out because facet joint osteoarthritis typically presents in older patients with mechanical, activity-worsened pain, not inflammatory-pattern pain with morning stiffness, alternating buttock pain and associated uveitis in a young adult.', 4),
('e8000000-0000-0000-0000-000000000047', 'E', 'Fibromyalgia', false, 'Ruled out because fibromyalgia causes widespread chronic pain and tenderness at multiple sites without the specific inflammatory back pain pattern, reduced spinal mobility, or the association with uveitis described here.', 5),
('e8000000-0000-0000-0000-000000000048', 'A', 'Vascular (intermittent) claudication due to peripheral arterial disease', false, 'Ruled out because vascular claudication is typically relieved simply by stopping and standing still (rest), regardless of posture, and would also cause symptoms with cycling due to ongoing muscular oxygen demand; the specific relief with flexion and absence of symptoms with cycling favour a neurogenic rather than vascular cause.', 1),
('e8000000-0000-0000-0000-000000000048', 'B', 'Cauda equina syndrome', false, 'Ruled out because there is no saddle anaesthesia or bladder/bowel dysfunction described, and the pattern is a predictable, posture-related claudication rather than the acute, progressive red flag presentation of cauda equina syndrome.', 2),
('e8000000-0000-0000-0000-000000000048', 'C', 'Neurogenic claudication due to lumbar spinal canal narrowing, relieved by spinal flexion', true, 'Correct. Neurogenic claudication from lumbar spinal stenosis classically causes bilateral or unilateral leg pain/heaviness on walking, relieved by flexion of the spine (leaning forward or sitting), because flexion increases the space within the spinal canal; the lack of symptoms while cycling (a flexed posture) is a classic distinguishing clue from vascular claudication.', 3),
('e8000000-0000-0000-0000-000000000048', 'D', 'Piriformis syndrome', false, 'Ruled out because piriformis syndrome typically causes buttock pain aggravated by sitting or specific hip movements, not a distance-dependent walking-induced claudication pattern relieved by spinal flexion.', 4),
('e8000000-0000-0000-0000-000000000048', 'E', 'Deep vein thrombosis', false, 'Ruled out because DVT causes persistent unilateral leg swelling and pain rather than an exertional, posture-dependent claudication pattern that resolves with flexion and rest.', 5),
('e8000000-0000-0000-0000-000000000049', 'A', 'Arrange urgent CT (or MRI) of the spine and treat as a high suspicion for unstable fracture despite normal plain radiographs', true, 'Correct. Patients with ankylosing spondylitis and a fused, rigid spine are at very high risk of unstable fractures even after low-energy trauma, and plain radiographs frequently miss these fractures due to altered anatomy and osteoporosis; new neurological signs and ongoing severe pain in this context mandate urgent further imaging (CT or MRI) and treatment as a high suspicion for unstable fracture regardless of an apparently normal initial radiograph, given the high risk of spinal cord injury from an occult unstable fracture.', 1),
('e8000000-0000-0000-0000-000000000049', 'B', 'Reassure the patient that the normal radiograph excludes a significant spinal injury', false, 'Ruled out because plain radiographs have a high miss rate for fractures in a fused ankylosing spondylitis spine, and new neurological signs after even low-energy trauma in this population must never be dismissed on the basis of a normal plain film.', 2),
('e8000000-0000-0000-0000-000000000049', 'C', 'Discharge with simple analgesia and safety-netting advice only', false, 'Ruled out because the combination of a fused spondylitic spine, low-energy trauma, severe pain and new neurological signs represents a high-risk situation for occult unstable fracture that requires urgent further imaging, not discharge.', 3),
('e8000000-0000-0000-0000-000000000049', 'D', 'Mobilise the patient early to prevent deconditioning before any further imaging', false, 'Ruled out because early mobilisation in a patient with a suspected unstable spinal fracture and new neurological signs risks catastrophic spinal cord injury; the spine should be protected and further imaging obtained urgently first.', 4),
('e8000000-0000-0000-0000-000000000049', 'E', 'Refer only for physiotherapy assessment of gait', false, 'Ruled out because this does not address the urgent need to investigate a potentially unstable, occult spinal fracture with new neurological compromise in a very high-risk patient group.', 5),
('e8000000-0000-0000-0000-000000000050', 'A', 'Unstable cervical spine fracture', false, 'Ruled out because there is no midline bony tenderness, no neurological deficit, and the mechanism was low-speed with the patient able to walk immediately afterward; this clinical picture is reassuring against a significant unstable fracture, though clinical decision rules should still be applied to guide any imaging need.', 1),
('e8000000-0000-0000-0000-000000000050', 'B', 'Cervical disc herniation with radiculopathy', false, 'Ruled out because there are no arm symptoms (pain, numbness, weakness) described, which would be expected with radiculopathy from disc herniation; this is a diffuse neck pain/stiffness picture rather than a radicular one.', 2),
('e8000000-0000-0000-0000-000000000050', 'C', 'Vertebral artery dissection', false, 'Ruled out because there is no headache, neurological deficit or other feature suggestive of vertebral artery dissection; this is a straightforward soft tissue neck strain presentation.', 3),
('e8000000-0000-0000-0000-000000000050', 'D', 'Whiplash-associated soft tissue neck injury', true, 'Correct. Neck pain and stiffness developing after a low-speed collision, in a fully alert patient with no midline bony tenderness, no neurological deficit and no high-risk features, is consistent with a soft tissue whiplash injury, which is managed conservatively with analgesia and early mobilisation/gentle exercise rather than prolonged immobilisation.', 4),
('e8000000-0000-0000-0000-000000000050', 'E', 'Cervical spondylotic myelopathy', false, 'Ruled out because myelopathy would present with signs of spinal cord dysfunction (e.g. gait disturbance, hyperreflexia, sensory changes), which are absent here; this is an acute soft tissue injury, not a chronic degenerative cord condition.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e8000000-0000-0000-0000-000000000001', 'Osteoarthritis typically causes mechanical pain worse with activity and brief morning stiffness (<30 minutes), unlike inflammatory arthritis.', 1),
('e8000000-0000-0000-0000-000000000001', 'Plain weight-bearing radiographs are first-line for suspected osteoarthritis and show joint space narrowing, osteophytes, subchondral sclerosis and cysts.', 2),
('e8000000-0000-0000-0000-000000000001', 'NICE recommends a clinical diagnosis of osteoarthritis without imaging if the patient is over 45, has activity-related pain and no morning stiffness >30 minutes; imaging is used when the diagnosis is uncertain or to guide referral.', 3),
('e8000000-0000-0000-0000-000000000002', 'Referral for joint replacement should be considered when conservative treatment has failed and osteoarthritis significantly impacts quality of life, regardless of age alone.', 1),
('e8000000-0000-0000-0000-000000000002', 'Arthroscopic lavage/debridement is not recommended for knee osteoarthritis as it lacks proven benefit over conservative management.', 2),
('e8000000-0000-0000-0000-000000000002', 'Intra-articular steroid injections give short-term relief only and should not replace referral when symptoms are severe and refractory.', 3),
('e8000000-0000-0000-0000-000000000003', 'Prosthetic joint infection should be suspected with increasing pain, wound discharge, erythema, fever and rising CRP after joint replacement, and requires urgent orthopaedic referral.', 1),
('e8000000-0000-0000-0000-000000000003', 'Early prosthetic joint infection may be managed with debridement, antibiotics and implant retention (DAIR) if caught promptly; delayed presentations may need implant removal.', 2),
('e8000000-0000-0000-0000-000000000003', 'Blind antibiotic treatment without specialist assessment/culture risks masking infection and should be avoided in suspected prosthetic joint infection.', 3),
('e8000000-0000-0000-0000-000000000004', 'Major lower limb orthopaedic surgery (hip/knee replacement) carries high VTE risk and warrants combined mechanical and pharmacological prophylaxis unless contraindicated.', 1),
('e8000000-0000-0000-0000-000000000004', 'Prophylactic-dose anticoagulation (not therapeutic dose) is used for VTE prevention after arthroplasty.', 2),
('e8000000-0000-0000-0000-000000000004', 'Pre-existing anticoagulation (e.g. rivaroxaban for AF) needs careful perioperative bridging/interruption planning distinct from post-operative VTE prophylaxis dosing.', 3),
('e8000000-0000-0000-0000-000000000005', 'First CMC joint osteoarthritis presents with base-of-thumb pain worsened by pinch/grip, a positive grind test, and joint squaring on examination.', 1),
('e8000000-0000-0000-0000-000000000005', 'Normal inflammatory markers with a chronic mechanical pattern favour osteoarthritis over an inflammatory arthropathy.', 2),
('e8000000-0000-0000-0000-000000000005', $x$De Quervain's tenosynovitis and carpal tunnel syndrome are important differentials for hand/wrist pain but have distinct examination findings (Finkelstein's test; median nerve sensory/motor signs respectively).$x$, 3),
('e8000000-0000-0000-0000-000000000006', 'Posterior hip dislocation classically presents with a shortened, adducted, internally rotated limb after a flexion/adduction/internal rotation movement, especially with a posterior surgical approach.', 1),
('e8000000-0000-0000-0000-000000000006', 'Patients after posterior-approach hip replacement are advised to avoid combined hip flexion beyond 90 degrees, adduction and internal rotation to reduce dislocation risk.', 2),
('e8000000-0000-0000-0000-000000000006', 'Suspected prosthetic dislocation requires urgent radiographs and orthopaedic referral for reduction, usually under sedation or anaesthesia.', 3),
('e8000000-0000-0000-0000-000000000007', $x$Heberden's nodes affect the DIP joints; Bouchard's nodes affect the PIP joints — both are seen in nodal hand osteoarthritis.$x$, 1),
('e8000000-0000-0000-0000-000000000007', 'Nodal hand osteoarthritis is more common in women and often has a strong genetic component.', 2),
('e8000000-0000-0000-0000-000000000007', 'Bony joint swellings should be distinguished from soft tissue swelling (synovitis) seen in inflammatory arthropathies like rheumatoid arthritis.', 3),
('e8000000-0000-0000-0000-000000000008', 'Metal-on-metal hip implants are associated with adverse reaction to metal debris (ARMD), presenting with elevated serum cobalt/chromium, pain, and peri-prosthetic pseudotumours.', 1),
('e8000000-0000-0000-0000-000000000008', 'Patients with metal-on-metal implants require specific long-term surveillance including metal ion levels and imaging per regulatory guidance (e.g. MHRA).', 2),
('e8000000-0000-0000-0000-000000000008', 'ARMD may necessitate revision surgery to remove the metal-on-metal bearing and address soft tissue damage.', 3),
('e8000000-0000-0000-0000-000000000009', 'Core treatments for osteoarthritis recommended by NICE include therapeutic exercise and weight loss (if overweight), alongside patient education.', 1),
('e8000000-0000-0000-0000-000000000009', 'Weight loss reduces mechanical loading on weight-bearing joints like the knee and hip, improving symptoms in osteoarthritis.', 2),
('e8000000-0000-0000-0000-000000000009', 'Surgical referral for joint replacement is considered after conservative management has failed and quality of life is significantly affected, not as an initial step.', 3),
('e8000000-0000-0000-0000-000000000010', 'Mild leg length discrepancy is a recognised and often deliberately accepted consequence of hip replacement to optimise joint stability and soft tissue tension.', 1),
('e8000000-0000-0000-0000-000000000010', 'In the absence of pain, instability or radiographic abnormality, leg length discrepancy after hip replacement can be managed conservatively, including with a shoe raise.', 2),
('e8000000-0000-0000-0000-000000000010', 'Red flags requiring further investigation after hip replacement include significant pain, instability, inability to weight-bear, or radiographic evidence of loosening, fracture or dislocation.', 3),
('e8000000-0000-0000-0000-000000000011', 'Open fractures require prompt IV antibiotics, wound photography, saline-soaked dressing cover, and limb realignment/splinting as part of immediate management.', 1),
('e8000000-0000-0000-0000-000000000011', 'Repeated wound exposure and premature primary closure increase infection risk in open fractures; definitive debridement should occur in theatre.', 2),
('e8000000-0000-0000-0000-000000000011', 'Neurovascular status must be assessed and documented before and after any manipulation of a fractured limb.', 3),
('e8000000-0000-0000-0000-000000000012', 'Compartment syndrome presents with severe pain out of proportion to injury, poorly responsive to opioids, and pain on passive stretch of muscles in the affected compartment.', 1),
('e8000000-0000-0000-0000-000000000012', 'Distal pulses are often preserved in compartment syndrome until very late, so palpable pulses must never be used to exclude the diagnosis.', 2),
('e8000000-0000-0000-0000-000000000012', 'Management requires immediate removal of constrictive dressings/casts, keeping the limb at heart level (not elevated above it), and urgent surgical fasciotomy if pressures remain elevated.', 3),
('e8000000-0000-0000-0000-000000000013', 'A shortened, externally rotated leg with inability to weight-bear after a fall in an older adult is the classic presentation of a fractured neck of femur.', 1),
('e8000000-0000-0000-0000-000000000013', 'Osteoporosis, previous fragility fractures and bisphosphonate use are relevant risk factors to note in a suspected fragility fracture.', 2),
('e8000000-0000-0000-0000-000000000013', 'All suspected hip fractures require urgent plain radiographs (AP pelvis and lateral hip); if radiographs are normal but clinical suspicion remains, MRI or CT should be considered.', 3),
('e8000000-0000-0000-0000-000000000014', 'Supracondylar fractures are common in children and carry a significant risk of vascular injury (brachial artery) and nerve injury (anterior interosseous/median nerve).', 1),
('e8000000-0000-0000-0000-000000000014', 'A pale, cool limb with reduced/absent pulses after a supracondylar fracture is a vascular emergency requiring urgent reduction, with surgical exploration if perfusion does not recover.', 2),
('e8000000-0000-0000-0000-000000000014', $x$Delayed or missed vascular compromise in supracondylar fractures can lead to Volkmann's ischaemic contracture, a severe and disabling complication.$x$, 3),
('e8000000-0000-0000-0000-000000000015', $x$Colles' fracture: dorsally displaced/angulated distal radius fracture from a fall onto an outstretched hand ('dinner fork' deformity).$x$, 1),
('e8000000-0000-0000-0000-000000000015', $x$Smith's fracture is the volar-displacement counterpart of Colles', from a fall onto a flexed wrist.$x$, 2),
('e8000000-0000-0000-0000-000000000015', 'Distal radius fractures are common fragility fractures in postmenopausal women and should prompt consideration of osteoporosis risk assessment.', 3),
('e8000000-0000-0000-0000-000000000016', 'Scaphoid fractures are often not visible on initial radiographs; clinical suspicion (snuffbox tenderness, FOOSH mechanism) should prompt immobilisation and repeat imaging.', 1),
('e8000000-0000-0000-0000-000000000016', 'The scaphoid has a retrograde blood supply, making it vulnerable to avascular necrosis if a fracture is missed or inadequately treated.', 2),
('e8000000-0000-0000-0000-000000000016', 'Persistent snuffbox tenderness after a fall onto an outstretched hand should never be dismissed on the basis of a single normal radiograph.', 3),
('e8000000-0000-0000-0000-000000000017', 'Fat embolism syndrome classically occurs 24-72 hours after long bone fracture (especially femur) with the triad of respiratory distress, neurological impairment and petechial rash.', 1),
('e8000000-0000-0000-0000-000000000017', 'Early stabilisation/fixation of long bone fractures reduces the risk of fat embolism syndrome.', 2),
('e8000000-0000-0000-0000-000000000017', 'Management of fat embolism syndrome is supportive (oxygen, respiratory support), as there is no specific reversal treatment.', 3),
('e8000000-0000-0000-0000-000000000018', 'Salter-Harris classification describes paediatric growth plate fractures: I (physis only), II (physis + metaphysis, most common), III (physis + epiphysis), IV (all three), V (crush injury).', 1),
('e8000000-0000-0000-0000-000000000018', 'Growth plate fractures carry a risk of growth disturbance, particularly types III, IV and V, which involve the epiphysis or are crush injuries.', 2),
('e8000000-0000-0000-0000-000000000018', $x$A helpful mnemonic is 'SALTR': Straight across, Above, Lower, Through, Ruined (crush), corresponding to types I-V.$x$, 3),
('e8000000-0000-0000-0000-000000000019', 'Increasing pain, swelling, discolouration and delayed capillary refill in a limb in a cast should raise concern for cast tightness or compartment syndrome and requires urgent cast loosening/splitting.', 1),
('e8000000-0000-0000-0000-000000000019', 'Casts should always allow room for post-injury swelling; patients must be given clear safety-netting advice about red flag symptoms to report immediately.', 2),
('e8000000-0000-0000-0000-000000000019', $x$Failure to act promptly on evolving vascular compromise in a casted limb can lead to permanent ischaemic damage or Volkmann's contracture.$x$, 3),
('e8000000-0000-0000-0000-000000000020', $x$Atypical femoral fractures are associated with prolonged bisphosphonate use and present as subtrochanteric/diaphyseal transverse fractures with lateral cortical thickening ('beaking'), often after minimal trauma.$x$, 1),
('e8000000-0000-0000-0000-000000000020', 'Prodromal thigh or groin pain in a patient on long-term bisphosphonates should prompt imaging to exclude an evolving atypical fracture before complete fracture occurs.', 2),
('e8000000-0000-0000-0000-000000000020', 'Management often includes consideration of stopping bisphosphonate therapy and orthopaedic referral for fixation; the contralateral femur should also be imaged as these fractures can be bilateral.', 3),
('e8000000-0000-0000-0000-000000000021', 'Anterior shoulder dislocation is the most common type, usually from a fall onto an abducted, externally rotated arm, causing a squared-off shoulder and anterior fullness.', 1),
('e8000000-0000-0000-0000-000000000021', 'Neurovascular assessment (particularly axillary nerve and brachial plexus) is essential before and after any reduction attempt, given proximity of these structures to the joint.', 2),
('e8000000-0000-0000-0000-000000000021', 'Post-reduction radiographs are required to confirm successful relocation and exclude associated fractures (e.g. Hill-Sachs or Bankart lesions).', 3),
('e8000000-0000-0000-0000-000000000022', 'ACL rupture classically presents with a pivoting injury, an audible pop, and rapid haemarthrosis, with positive Lachman and anterior drawer tests.', 1),
('e8000000-0000-0000-0000-000000000022', 'The Lachman test is generally considered more sensitive than the anterior drawer test for detecting ACL injury.', 2),
('e8000000-0000-0000-0000-000000000022', 'MRI is the investigation of choice to confirm ACL rupture and assess for associated meniscal or other ligamentous injury.', 3),
('e8000000-0000-0000-0000-000000000023', 'Achilles tendon rupture classically presents with a sudden sharp calf pain (often described as being kicked), a palpable gap, and weakness of plantarflexion.', 1),
('e8000000-0000-0000-0000-000000000023', 'The Simmonds-Thompson (calf squeeze) test is a key bedside test: absence of plantarflexion on squeezing the calf indicates tendon discontinuity.', 2),
('e8000000-0000-0000-0000-000000000023', 'Management options include conservative treatment (immobilisation in plantarflexion) or surgical repair depending on patient factors and local protocols; urgent orthopaedic referral is required.', 3),
('e8000000-0000-0000-0000-000000000024', 'ACJ injury typically follows a direct fall onto the shoulder (not an outstretched hand) and causes a step deformity at the distal clavicle.', 1),
('e8000000-0000-0000-0000-000000000024', 'The Rockwood classification grades ACJ injuries by severity, guiding conservative versus surgical management.', 2),
('e8000000-0000-0000-0000-000000000024', 'Most low-grade ACJ injuries are managed conservatively with a sling and analgesia; higher-grade injuries may need orthopaedic input.', 3),
('e8000000-0000-0000-0000-000000000025', 'The Ottawa Ankle Rules guide the need for radiographs: imaging is indicated only if there is bony tenderness at the posterior edge/tip of either malleolus or the patient cannot weight-bear for four steps both immediately and in the emergency department.', 1),
('e8000000-0000-0000-0000-000000000025', 'The Ottawa Foot Rules similarly guide imaging for midfoot injuries, based on tenderness at the base of the fifth metatarsal or navicular, or inability to weight-bear.', 2),
('e8000000-0000-0000-0000-000000000025', 'Most acute lateral ankle ligament sprains are managed conservatively with rest, ice, compression, elevation, analgesia and early functional rehabilitation.', 3),
('e8000000-0000-0000-0000-000000000026', 'Subacromial impingement (rotator cuff tendinopathy) classically causes a painful arc between roughly 60-120 degrees of abduction with preserved passive range of movement.', 1),
('e8000000-0000-0000-0000-000000000026', 'Adhesive capsulitis differs by causing global restriction of both active and passive movement, especially external rotation.', 2),
('e8000000-0000-0000-0000-000000000026', 'Occupations or activities involving repetitive overhead movement are risk factors for subacromial impingement/rotator cuff pathology.', 3),
('e8000000-0000-0000-0000-000000000027', 'The axillary nerve is the most commonly injured nerve in anterior shoulder dislocation, due to its course close to the inferior joint capsule.', 1),
('e8000000-0000-0000-0000-000000000027', $x$Axillary nerve injury causes weakness of deltoid (shoulder abduction) and sensory loss over the 'regimental badge' area of the lateral upper arm.$x$, 2),
('e8000000-0000-0000-0000-000000000027', 'Neurovascular status must always be assessed and documented before and after reduction of any shoulder dislocation.', 3),
('e8000000-0000-0000-0000-000000000028', $x$Lateral epicondylitis ('tennis elbow') causes lateral elbow pain reproduced by resisted wrist extension, typically from repetitive gripping/extension activities.$x$, 1),
('e8000000-0000-0000-0000-000000000028', $x$Medial epicondylitis ('golfer's elbow') is the counterpart affecting the medial epicondyle, reproduced by resisted wrist flexion.$x$, 2),
('e8000000-0000-0000-0000-000000000028', 'Management is typically conservative: activity modification, physiotherapy, and analgesia; corticosteroid injections may give short-term relief but have higher recurrence rates.', 3),
('e8000000-0000-0000-0000-000000000029', $x$Knee dislocation carries a high risk of popliteal artery injury due to the artery's fixed anatomical course, even if the joint has spontaneously reduced.$x$, 1),
('e8000000-0000-0000-0000-000000000029', 'Hard signs of vascular injury (absent pulse, pallor, coolness, reduced sensation) mandate emergency vascular surgical referral, often with CT angiography to define injury before intervention.', 2),
('e8000000-0000-0000-0000-000000000029', 'Delayed recognition of popliteal artery injury after knee dislocation is a leading cause of limb amputation, so index of suspicion must remain high regardless of whether the joint has relocated.', 3),
('e8000000-0000-0000-0000-000000000030', $x$Meniscal tears classically occur with a twisting injury and present with joint line tenderness, effusion, and a positive McMurray's test.$x$, 1),
('e8000000-0000-0000-0000-000000000030', 'Normal ligament stability testing helps distinguish an isolated meniscal tear from cruciate or collateral ligament injury, though these injuries can co-exist.', 2),
('e8000000-0000-0000-0000-000000000030', 'MRI is the investigation of choice to confirm meniscal tears when clinical suspicion is high or symptoms persist.', 3),
('e8000000-0000-0000-0000-000000000031', 'Septic arthritis is a medical emergency: urgent joint aspiration for synovial fluid Gram stain/culture/crystals should be performed before or alongside starting empirical IV antibiotics, without delay.', 1),
('e8000000-0000-0000-0000-000000000031', 'Risk factors for septic arthritis include diabetes, immunosuppression, pre-existing joint disease, prosthetic joints and intravenous drug use.', 2),
('e8000000-0000-0000-0000-000000000031', 'Intra-articular corticosteroid injection is contraindicated when septic arthritis is suspected, as it can accelerate joint destruction and mask signs of infection.', 3),
('e8000000-0000-0000-0000-000000000032', 'Reactive arthritis follows gastrointestinal (Campylobacter, Salmonella, Shigella) or genitourinary (Chlamydia) infection, typically 1-4 weeks later, with a sterile inflammatory joint aspirate.', 1),
('e8000000-0000-0000-0000-000000000032', $x$The classic triad is arthritis, conjunctivitis and urethritis ('can't see, can't pee, can't climb a tree'), though not all features need be present.$x$, 2),
('e8000000-0000-0000-0000-000000000032', 'Septic arthritis must always be actively excluded (via joint aspiration culture) before confidently diagnosing reactive arthritis, as the two can appear clinically similar.', 3),
('e8000000-0000-0000-0000-000000000033', 'Acute osteomyelitis in children classically presents with fever, refusal to weight-bear, and focal bone tenderness/swelling, most often at the metaphysis of long bones.', 1),
('e8000000-0000-0000-0000-000000000033', 'Plain radiographs are often normal in early osteomyelitis; MRI is the most sensitive imaging modality and is used to confirm diagnosis and extent.', 2),
('e8000000-0000-0000-0000-000000000033', 'Blood cultures and, where possible, bone aspiration/biopsy should be obtained before starting antibiotics to guide targeted therapy, provided this does not unduly delay treatment in a septic child.', 3),
('e8000000-0000-0000-0000-000000000034', 'Chronic prosthetic joint infection can present indolently, months to years after surgery, with gradual pain, intermittent low-grade fever and mildly raised inflammatory markers, unlike the more florid acute post-operative infection.', 1),
('e8000000-0000-0000-0000-000000000034', 'Low-virulence organisms (e.g. coagulase-negative staphylococci, Cutibacterium acnes) are classic causes of chronic prosthetic joint infection.', 2),
('e8000000-0000-0000-0000-000000000034', 'Suspected prosthetic joint infection requires specialist orthopaedic assessment, often including joint aspiration and imaging, before attributing symptoms to aseptic loosening or an unrelated cause.', 3),
('e8000000-0000-0000-0000-000000000035', 'Vertebral osteomyelitis with epidural abscess is a serious infection requiring urgent multidisciplinary assessment (spinal surgery, microbiology) due to the risk of spinal cord compression.', 1),
('e8000000-0000-0000-0000-000000000035', 'Risk factors include intravenous drug use, diabetes, immunosuppression and recent bacteraemia/endocarditis.', 2),
('e8000000-0000-0000-0000-000000000035', 'Persistent, worsening back pain that is not relieved by rest and worse at night, especially with fever and risk factors, should prompt urgent investigation for spinal infection.', 3),
('e8000000-0000-0000-0000-000000000036', 'Disseminated gonococcal infection classically presents with a triad of migratory polyarthralgia/tenosynovitis, dermatitis (pustular or vesicular skin lesions), and a history of sexual exposure.', 1),
('e8000000-0000-0000-0000-000000000036', 'N. gonorrhoeae is an important cause of septic arthritis in sexually active young adults and should prompt sexual health screening and contact tracing.', 2),
('e8000000-0000-0000-0000-000000000036', 'Joint aspiration with culture (and additional swabs from mucosal sites) should be sent, though gonococcal culture yield from joint fluid can be lower than for other organisms, so clinical suspicion remains important.', 3),
('e8000000-0000-0000-0000-000000000037', 'Immunosuppressed patients (e.g. rheumatoid arthritis on methotrexate/steroids) are at increased risk of septic arthritis, which can mimic a disease flare and must always be actively excluded.', 1),
('e8000000-0000-0000-0000-000000000037', $x$Unusually high inflammatory markers, atypical examination findings, or a history that a flare 'feels different' should raise suspicion for infection rather than reassurance that it is a typical flare.$x$, 2),
('e8000000-0000-0000-0000-000000000037', 'Urgent joint aspiration for Gram stain, culture and crystal analysis is essential before committing to a diagnosis of a rheumatoid flare in this context.', 3),
('e8000000-0000-0000-0000-000000000038', $x$A positive 'probe-to-bone' test in a diabetic foot ulcer significantly increases the likelihood of underlying osteomyelitis and should prompt further investigation and specialist referral.$x$, 1),
('e8000000-0000-0000-0000-000000000038', 'Diabetic foot osteomyelitis requires multidisciplinary management (diabetic foot service, microbiology, sometimes vascular/orthopaedic input) including imaging and often bone biopsy/culture to guide antibiotic therapy.', 2),
('e8000000-0000-0000-0000-000000000038', 'Distinguishing osteomyelitis from Charcot neuroarthropathy can be clinically challenging and may require MRI and specialist input, as both can coexist in diabetic feet.', 3),
('e8000000-0000-0000-0000-000000000039', 'Transient synovitis is the most common cause of acute hip pain/limp in young children, often following a viral infection, with a well child and only mildly raised inflammatory markers.', 1),
('e8000000-0000-0000-0000-000000000039', 'Septic arthritis must always be actively considered and excluded in a limping child, especially if the child appears unwell, febrile, or has significantly raised inflammatory markers or inability to weight-bear.', 2),
('e8000000-0000-0000-0000-000000000039', 'Clinical prediction tools (e.g. Kocher criteria: fever, inability to weight-bear, raised ESR/CRP, raised white cell count) can help distinguish septic arthritis from transient synovitis, but clinical judgement and safety-netting remain essential.', 3),
('e8000000-0000-0000-0000-000000000040', 'Vertebral discitis/osteomyelitis typically requires prolonged (often at least 6 weeks) targeted antibiotic therapy guided by microbiology/infectious diseases input, due to poor antibiotic penetration into bone/disc tissue.', 1),
('e8000000-0000-0000-0000-000000000040', 'Surgery in spinal infection is reserved for specific indications such as epidural abscess with neurological compromise, spinal instability, or failure of medical therapy.', 2),
('e8000000-0000-0000-0000-000000000040', 'Blood cultures and, where feasible, image-guided biopsy should be used to identify the causative organism and guide targeted (rather than broad empirical) antibiotic therapy wherever possible.', 3),
('e8000000-0000-0000-0000-000000000041', 'Cauda equina syndrome red flags include bilateral leg pain/sciatica, saddle (perineal) anaesthesia, bladder or bowel dysfunction (retention, incontinence, reduced awareness of filling), and reduced anal tone.', 1),
('e8000000-0000-0000-0000-000000000041', 'Suspected cauda equina syndrome requires emergency same-day MRI of the whole spine and urgent spinal/neurosurgical referral for possible decompression.', 2),
('e8000000-0000-0000-0000-000000000041', 'Delayed diagnosis and treatment of cauda equina syndrome can result in permanent bladder, bowel and sexual dysfunction, and lower limb paralysis.', 3),
('e8000000-0000-0000-0000-000000000042', 'Sacral sparing (preserved perianal sensation, voluntary anal contraction, or great toe flexor function) indicates an incomplete spinal cord injury, regardless of how severe the injury appears elsewhere.', 1),
('e8000000-0000-0000-0000-000000000042', 'Priapism can occur after acute spinal cord injury due to disruption of normal autonomic control.', 2),
('e8000000-0000-0000-0000-000000000042', 'All patients with suspected acute traumatic spinal cord injury require full spinal immobilisation during initial assessment and urgent imaging and specialist spinal input.', 3),
('e8000000-0000-0000-0000-000000000043', 'Simple mechanical back pain without red flags (fever, weight loss, night pain, saddle anaesthesia, bladder/bowel dysfunction, progressive neurological deficit) can be managed conservatively without urgent imaging.', 1),
('e8000000-0000-0000-0000-000000000043', 'Patients with non-specific back pain should be encouraged to remain active rather than rest, as prolonged bed rest worsens outcomes.', 2),
('e8000000-0000-0000-0000-000000000043', 'Red flag features for back pain should always be actively screened for at every assessment, as their presence would change management significantly.', 3),
('e8000000-0000-0000-0000-000000000044', 'Osteoporotic vertebral compression fractures classically occur after minimal trauma (e.g. bending, coughing) in patients with risk factors for osteoporosis, and often cause progressive height loss over time.', 1),
('e8000000-0000-0000-0000-000000000044', 'Absence of neurological deficit and red flags for malignancy or infection supports a diagnosis of simple osteoporotic fracture, but these should always be actively screened for.', 2),
('e8000000-0000-0000-0000-000000000044', 'Management includes analgesia, addressing underlying osteoporosis (bone protection therapy), and considering vertebroplasty/kyphoplasty in selected persistent cases.', 3),
('e8000000-0000-0000-0000-000000000045', 'High-risk mechanisms (e.g. diving injuries, falls from height, high-speed collisions) with midline cervical tenderness require imaging before spinal precautions are removed, regardless of GCS.', 1),
('e8000000-0000-0000-0000-000000000045', 'CT is the first-line imaging modality for suspected cervical spine injury in adults with high-risk features, per current major trauma guidance, superseding plain radiographs in this context.', 2),
('e8000000-0000-0000-0000-000000000045', 'Spinal immobilisation should be maintained throughout assessment until the spine has been definitively cleared clinically or radiologically by an appropriately trained clinician.', 3),
('e8000000-0000-0000-0000-000000000046', 'Red flags for metastatic spinal cord compression include a history of malignancy, night/rest pain, progressive limb weakness, bladder or bowel dysfunction, and unintentional weight loss.', 1),
('e8000000-0000-0000-0000-000000000046', 'Metastatic spinal cord compression is an oncological emergency requiring same-day MRI of the whole spine, urgent specialist referral, and often immediate high-dose corticosteroids to reduce cord oedema while awaiting definitive treatment.', 2),
('e8000000-0000-0000-0000-000000000046', 'Any new back pain in a patient with a history of cancer should be assessed for red flag features of cord compression at first presentation, as delayed recognition worsens neurological outcomes.', 3),
('e8000000-0000-0000-0000-000000000047', 'Inflammatory back pain (morning stiffness improving with exercise, worse with rest) in a young adult, especially with alternating buttock pain, suggests axial spondyloarthritis/ankylosing spondylitis.', 1),
('e8000000-0000-0000-0000-000000000047', 'Extra-articular associations of ankylosing spondylitis include anterior uveitis, inflammatory bowel disease and psoriasis.', 2),
('e8000000-0000-0000-0000-000000000047', $x$Reduced chest expansion and reduced spinal mobility (e.g. reduced lumbar flexion, Schober's test) reflect axial involvement and can be assessed clinically to support the diagnosis.$x$, 3),
('e8000000-0000-0000-0000-000000000048', 'Neurogenic claudication from lumbar spinal stenosis is classically relieved by spinal flexion (leaning forward, sitting) and is notably absent or minimal with cycling, unlike vascular claudication.', 1),
('e8000000-0000-0000-0000-000000000048', 'Vascular claudication is typically relieved simply by stopping/standing still, irrespective of posture, and worsens with any sustained exertion including cycling.', 2),
('e8000000-0000-0000-0000-000000000048', 'Absence of cauda equina red flags (saddle anaesthesia, bladder/bowel dysfunction) makes an emergency presentation less likely, but ongoing symptoms should still be assessed and monitored for any red flag development.', 3),
('e8000000-0000-0000-0000-000000000049', 'Patients with ankylosing spondylitis (fused, rigid spine) are at very high risk of unstable spinal fractures even from low-energy trauma, and plain radiographs frequently fail to detect these fractures.', 1),
('e8000000-0000-0000-0000-000000000049', 'New neurological signs after trauma in a patient with a fused spondylitic spine should prompt urgent CT or MRI, treating the situation as a high-risk unstable fracture until proven otherwise.', 2),
('e8000000-0000-0000-0000-000000000049', 'The rigid, osteoporotic spine in long-standing ankylosing spondylitis behaves biomechanically like a single long lever arm, making fractures more likely to be unstable and multi-level compared with the normal spine.', 3),
('e8000000-0000-0000-0000-000000000050', 'Whiplash-associated disorder describes soft tissue neck injury following an acceleration-deceleration mechanism, typically presenting with neck pain/stiffness without neurological deficit.', 1),
('e8000000-0000-0000-0000-000000000050', 'Clinical decision tools (e.g. Canadian C-spine rule) help determine whether imaging is needed in alert, stable trauma patients with neck pain, based on risk factors and clinical findings such as midline tenderness.', 2),
('e8000000-0000-0000-0000-000000000050', 'Management of simple whiplash is conservative: analgesia, reassurance and encouragement of early mobilisation/gentle range-of-motion exercise rather than prolonged collar immobilisation, which can worsen stiffness.', 3);
